local P = LoreForeverPacks.Begin("LoreForever_Lang_deDE")
P.entries["zone:tirisfal"] = {n="Tirisfal",s="Tirisfal ist das unheimliche nördliche Gebiet von Lordaeron und dient nun als Herzland von Fürstin Sylvanas Windläufer und der Verlassenen. Unter verdorbenen Himmeln und verrottenden Ästen liegen gefallene Anwesen, ruhende Krypten und die riesige unterirdische Hauptstadt der Unterstadt. Umgeben von hirnloser Geißel und eifrigen Scharlachroten Kreuzzüglern ist es ein gefährliches Reich, in dem Untote mit freiem Willen um ihr Überleben kämpfen.",h="Tirisfal ist das unheimliche nördliche Gebiet von Lordaeron und dient nun als Herzland von Fürstin Sylvanas...",kw={"agamand","balnir","brill","todesend","verlassene","tiefland","lordaeron","scharlachroter kreuzzug","sylvanas","tirisfal","unterstadt"},ang={["class:Priest"]="Historische heilige Stätten wie Faols Ruheplatz – das Grab von Erzbischof Alonsus Faol, dem Gründer der Silbernen Hand – liegen hier, durch den Tod entstellt und umkämpft zwischen Eiferern und Schattenpriestern.",["faction:Alliance"]="Für die überlebenden Nationen der Allianz ist Tirisfal ein tragisches Denkmal für den Fall Lordaerons, gefüllt mit den entweihten Gräbern ehemaliger Glaubensbrüder und -schwestern.",["faction:Horde"]="Tirisfal ist die entscheidende Bastion der Horde in den nördlichen Östlichen Königreichen, die diplomatische Beziehungen zu den Verlassenen festigt und gleichzeitig menschliche Extremisten und die Geißel abwehrt.",["race:Undead"]="Dies ist Eure angestammte Heimat gleich zweimal: das Königreich, das Ihr im Leben aufgebaut habt, und der unsichere Zufluchtsort, den Ihr im Untod unter Fürstin Sylvanas verteidigen müsst."},sec={{t="Ein Land in der Dämmerung",b="Einst die fruchtbare Wiege der Menschheit, ist Tirisfal unter dem Fluch der Seuche des Lichkönigs verdorrt. Die Sonne dringt nur selten durch die trübe Finsternis und wirft einen ewigen, krankhaft blassen Schein auf sterbende Wälder, vernachlässigte Kürbisfelder und kalte Küstenhügel. Während Überreste alter Bauernhöfe wie Agamands Mühlen und Balnirs Bauernhof bestehen bleiben, wurden ihre ehemaligen Herren größtenteils in Massengräber gespült oder sind als ruhelose Tote auferstanden. Trotz der Verwüstung durchdringt eine dunkle Widerstandskraft die Landschaft, verankert durch Städte wie Brill und den abgeschiedenen Zufluchtsort Todesend, wo frisch erwachte Verlassene lernen, ihr zweites Leben zu ertragen."},{t="Ein Krieg an zwei Fronten",b="Obwohl Fürstin Sylvanas die Herrschaft über die Region von den unterirdischen Ruinen von Lordaeron aus beansprucht, sind die Verlassenen weiterhin von allen Seiten bedrängt. Überreste von Geißel-Schergen befallen immer noch Senken, Felder und verfallene Krypten und sind dem Frostthron von Nordend vollständig untertan. Im Osten hat der fanatische Scharlachrote Kreuzzug das nördliche Tirisfal zu seiner Hauptbastion gemacht und operiert vom Scharlachroten Kloster aus. Eifrig der Ausrottung aller untoten Kreaturen verschrieben, führen ihre Außenposten und Patrouillen einen ständigen Guerillakrieg gegen Kundschafter der Verlassenen und zivile Reisende."},{t="Echos der alten Vergangenheit",b="Lange bevor menschliche Königreiche ihre ersten Monarchen krönten, trug Tirisfal ein altes Vermächtnis. Exilanten der Hochelfen versuchten kurzzeitig, sich in diesen Wäldern niederzulassen, bevor schattenhafte Energien tief unter der Erde begannen, sie in den Wahnsinn zu treiben, was sie zur Abwanderung in den Norden veranlasste. In späteren Jahrhunderten wählte die geheime sterbliche Kabale, bekannt als der Rat von Tirisfal, diese schattigen Haine, um einsame Wächter zu stärken und Azeroth vor dämonischem Eindringen zu schützen."}},faq={{q="Warum ist der Himmel grün und das Land verrottet?",a="Während des Dritten Krieges entfesselten Prinz Arthas und die Geißel die Seuche des Untodes über das Königreich Lordaeron. Die magische Fäulnis vergiftete nicht nur die Bevölkerung, sondern auch den Boden, die Bäume und das Wasser selbst und hinterließ das Gebiet in einem ewigen Zustand unheimlichen, krankhaften Verfalls.",al={"warum ist tirisfal verdorben","was geschah mit tirisfal","warum stirbt tirisfal"}},{q="Was ist der Unterschied zwischen den Verlassenen und der Geißel hier?",a="Die Verlassenen sind Untote, die sich nach der Schlacht am Hyjal von der telepathischen Beherrschung des Lichkönigs befreit haben und sich aus freiem Willen dazu entschlossen haben, Fürstin Sylvanas Windläufer zu folgen. Die Geißel, die auf den Bauernhöfen und in den Ruinen umherstreift, bleibt aus hirnlosen Sklaven bestehen, die an die Befehle des Lichkönigs gebunden sind.",al={"verlassene gegen geißel","warum greifen zombies untote an","sind alle untoten böse"}},{q="Wer sind die rotgepanzerten Soldaten, die Reisende angreifen?",a="Sie gehören zum Scharlachroten Kreuzzug, einer kompromisslosen Splittergruppe ehemaliger Paladine der Silbernen Hand und Überlebender. Davon überzeugt, dass alle Untoten unrettbare Abscheulichkeiten sind, die durch Schwert und Feuer gereinigt werden müssen, richten sie sowohl hirnlose Schergen als auch Verlassene mit freiem Willen mit fanatischem Hass hin.",al={"scharlachroter kreuzzug","rote menschen","kloster menschen"}},{q="Woher kommt der Name Tirisfal?",a="Der Name ist älter als jedes menschliche Königreich, und sein wahrer Ursprung ist in der Geschichte verloren gegangen. Er ist am besten durch den Rat von Tirisfal bekannt, den geheimen Orden der Magier, der die Wächter ermächtigte, Azeroth vor Dämonen zu schützen.",al={"bedeutung tirisfal","ursprung von tirisfal"}},{q="Wo beginnen neu erwachte Verlassene ihre Reise?",a="Neu erwachte Verlassene entsteigen den Krypten des Schattengrabes in Todesend, einer abgeschiedenen Stadt im südwestlichen Tirisfal. Dort bewerten Administratoren und Vollstrecker, ob die auferstandenen Toten den Verstand und die Loyalität besitzen, die erforderlich sind, um der Dunklen Fürstin zu dienen.",al={"startgebiet untote","wo ist todesend","startgebiet der verlassenen"}},{q="Wie verlassen Reisende Tirisfal in Richtung anderer Kontinente?",a="Ein großer, von Goblins betriebener Zeppelinturm befindet sich am Hang südlich von Brill, direkt außerhalb der Ruinen von Lordaeron. Diese Luftschiffe bieten eine direkte, regelmäßige Verbindung über die Meere nach Orgrimmar in Kalimdor und zum Basislager Grom'gol im Schlingendorntal.",al={"tirisfal zeppeline","wie kommt man nach orgrimmar","wie kommt man ins schlingendorntal"}}},fx={["6c272224"]={q="Was ist Tirisfal?",a="Tirisfal ist das Kernland der Verlassenen an der Nordküste von Lordaeron. Einst das friedliche, fruchtbare Herz eines stolzen Menschenkönigreichs, wurde es während des Dritter Krieg von der Pest des Untodes der Geißel verwüstet. Heute bedecken verseuchte Wälder und ein ewiges grünes Zwielicht die Hügel, eingerahmt von den Ruinen von Lordaeron und umgeben von feindseligen Eiferern, wilden Bestien und verbliebenen Untoten.",al={"was ist tirisfal","erzähl mir von tirisfal","tirisfal gebietsüberlieferung"}},["342b65f9"]={q="War dies schon immer das Land der Untoten?",a="Nein. Über tausende von Jahren war Tirisfal die Wiege der menschlichen Zivilisation und das blühende Herz des Königreichs von Lordaeron. Friedliche Gehöfte, wohlhabende Mühlen und kleine Weiler florierten unter König Terenas Menethil. Diese Ära endete gewaltsam während des Dritter Krieg, als Prinz Arthas und der Kult der Verdammten mit der Pest durch das Land fegten und die Bewohner in untote Sklaven verwandelten, bevor Sylvanas Windläufer sie befreite.",al={"war tirisfal immer untot","wer lebte hier vorher","tirisfal vor der pest"}},["4790468d"]={q="Wer lebt oder herrscht in Tirisfal?",a="Die Verlassenen beanspruchen Tirisfal unter der Herrschaft von Königin Sylvanas Windläufer aus der Unterstadt. Ihr Griff ist jedoch ständig umkämpft. Der fanatische Scharlachroter Kreuzzug befehligt Befestigungen und sein großes Kloster im Nordosten, während geistlose Geißel-Kreaturen verlassene Farmen durchstreifen. An der östlichen Grenze beim Bollwerk koordinieren die Verlassenen ihre Aktionen mit der Argentumdämmerung, um die Schrecken der Westliche Pestländer einzudämmen.",al={"wer regiert tirisfal","wer kontrolliert tirisfal","tirisfal fraktionen"}},["97ffdb73"]={q="Ist Tirisfal gefährlich?",a="Extrem gefährlich. Außerhalb der Mauern der Außenposten der Verlassenen begegnet Ihr geistlosen Resten der Geißel, wilden Gnollen, riesigen Arachniden und bösartiger Tierwelt, die von der Pest verseucht wurde. Noch schlimmer sind die Eiferer des Scharlachroter Kreuzzug, die jeden Untoten auf Sicht hinrichten. Im fernen Osten liegen die Westliche Pestländer, wo Monster, die weitaus tödlicher sind als alles in Tirisfal, die Unvorsichtigen zerfleischen werden.",al={"wie gefährlich ist tirisfal","tirisfal bedrohungen","ist es hier sicher"}},["30e6283a"]={q="Wer hat in Brill das Sagen?",a="Magistrat Sevren beaufsichtigt die zivile Verwaltung von Brill und leitet den Wiederaufbau und das tägliche Überleben der Stadt. Die militärische Autorität und die taktischen Operationen, insbesondere der Feldzug gegen den nahegelegenen Scharlachroter Kreuzzug, werden von Exekutor Zygand befehligt.",al={"brill anführer","wer führt brill","das sagen in brill"}},["3fc3649e"]={q="Wem untersteht Magistrat Sevren?",a="Sevren dient der Dunklen Fürstin, Königin Sylvanas Windläufer. Als Magistrat von Brill vertritt er die zivile Autorität der Krone der Verlassenen in der Region und arbeitet dabei direkt mit den königlichen Exekutoren und der Royal Apothecary Society mit Sitz in der Unterstadt zusammen.",al={"vorgesetzter von sevren","wem untersteht sevren","führungskette in brill"}},["381a9b46"]={q="Wo befindet sich die Bansheekönigin?",a="Fürstin Sylvanas Windläufer residiert im Royal Quarter der Unterstadt, tief unter den Ruinen von Capital City, direkt südlich von Brill. Von ihrem Thronsaal aus leitet sie die Verlassenen in ihrem Krieg gegen die Geißel und den The Scarlet Crusade.",al={"wo ist sylvanas","sylvanas finden","standort der bansheekönigin"}},e7993821={q="Was ist Brill?",a="Brill ist die wichtigste Siedlung der Verlassenen im zentralen Tirisfal, gelegen an der Kreuzung nördlich von Capital City. Einst eine lebende Siedlung unter der Barov-Herrschaft, wurde sie nach dem Dritten Krieg wiederaufgebaut, um neu erweckten Untoten einen Ort der Ruhe, des Handels und der Organisation zu bieten, bevor sie in die Welt hinausziehen.",al={"über brill","was für eine stadt ist brill","hintergrundgeschichte von brill"}},["529e09c8"]={q="Lebten hier früher einmal lebende Menschen?",a="Ja. Brill war einst eine ruhige menschliche Gemeinde innerhalb des Königreichs Lordaeron. Es wurde zum Ausgangspunkt früher Experimente mit der Seuche, die von Kel'Thuzad orchestriert wurden, was zu Massenopfern und riesigen Massengräbern führte, noch bevor Prinz Arthas jemals eintraf, um Nachforschungen anzustellen.",al={"lebten menschen in brill","lebendige geschichte von brill","wer lebte in brill"}},["7b7ff5e2"]={q="Was ist die Taverne Zur Galgenschlinge?",a="Die Taverne Zur Galgenschlinge ist der zentrale Treffpunkt und das Gasthaus von Brill. Sie bietet Schutz, üble Getränke und eine Atempause vor den düsteren Wäldern außerhalb. In ihren dunkleren Ecken halten die Verlassenen gefangene Feinde – wie etwa die Eiferer des The Scarlet Crusade – für finstere Versuche der Apotheker gefangen.",al={"taverne zur galgenschlinge","gasthaus von brill","was ist die taverne zur galgenschlinge"}},["0d8014ee"]={q="Was hat es mit Agamands Mühlen auf sich?",a="Agamands Mühlen war einst das wohlhabendste und produktivste landwirtschaftliche Anwesen in Tirisfal, berühmt für Mehl und Getreide. Als die Seuche zuschlug, wurde der gesamte Komplex überrannt und ein Gemetzel folgte. Heute steht es als eine verrottende, von Windmühlen gesäumte Ruine da, die von den untoten Dienern der Geißel heimgesucht wird.",al={"hintergrundgeschichte von agamands mühlen","was geschah mit agamands mühlen","agamands mühlen"}},["001d4abe"]={q="Wer waren die Agamands?",a="Die Agamands waren eine adelige, wohlhabende menschliche Dynastie, die die weitläufigen Mühlen entwickelte und Grundbesitz in ganz Tirisfal hielt, einschließlich Brill. Während des Dritten Krieges konnte ihr Reichtum sie nicht retten; die Familie fiel der Geißel zum Opfer und ihre reanimierten Patriarchen suchen weiterhin das Anwesen heim.",al={"familie agamand","wer lebte in agamands mühlen","die agamands"}},eeb96a2c={q="Warum sind sie uns gegenüber feindselig, wenn sie auch Untote sind?",a="Die Untoten, die Agamands Mühlen heimsuchen, haben ihren freien Willen nie wiedererlangt. Im Gegensatz zu den Verlassenen, die sich von der mentalen Kontrolle des Lichkönigs befreit haben, bleiben diese Kreaturen als gedankenlose Sklaven der Geißel gefangen, gezwungen, jeden Lebenden oder abtrünnigen Toten zu vernichten, der ihr Gebiet betritt.",al={"warum greifen die agamands uns an","warum sind die untoten der agamands feindselig","warum gegen andere untote kämpfen"}},a357af07={q="Wohin führt das alles nach Tirisfal?",a="Die meisten Verlassenen reisen durch den Gebirgspass nach Süden in den Silberwald, um bei der Sicherung der südlichen Grenze zu helfen und gegen Agenten von Dalaran und Rot Hide-Gnolle zu kämpfen. Alternativ bieten Zeppeline südlich von Brill eine Passage nach Orgrimmar oder zum Basislager Grom'gol auf der anderen Seite des Meeres.",al={"wohin nach tirisfal","nächstes gebiet nach tirisfal","nach tirisfal"}},["50336b90"]={q="Was ist die Unterstadt?",a="Die Unterstadt ist die weitläufige unterirdische Hauptstadt der Verlassenen, erbaut innerhalb der alten Abwasserkanäle, Krypten und Katakomben unter den zerstörten Ruinen von Lordaeron. Sie dient als Festung von Königin Sylvanas und als Command Center für die Operationen der Verlassenen in ganz Azeroth.",al={"was ist die unterstadt","hintergrundgeschichte der unterstadt","über die unterstadt"}},ddddba9f={q="Ist die Grenze zum Silberwald als Nächstes dran?",a="Ja. Wenn Ihr der Straße nach Süden aus Tirisfal folgt, gelangt Ihr direkt in den Silberwald. Dies ist die natürliche Fortsetzung Eures Dienstes für die Verlassenen, wo Ihr Euch der wachsenden Bedrohung entlang der südlichen Grenzen von Lordaeron stellt.",al={"als nächstes in den silberwald","gehe ich als nächstes in den silberwald","grenze zum silberwald"}},["789ead4d"]={q="Wie bin ich in Tirisfal gelandet?",a="Wenn Ihr ein neu erweckter Verlassener seid, seid Ihr während des Falls von Lordaeron an die Geißel gestorben und hier begraben worden. Da der Griff des Lichkönigs gebrochen ist, kehrte Euer freier Wille zurück und Ihr habt Euch aus dem Grab im abgelegenen Tal von Todesend herausgekämpft. Wenn Ihr zu den anderen Völkern der Horde gehört, seid Ihr wahrscheinlich über die Zeppeltürme zwischen Brill und der Unterstadt angekommen, die dieses verseuchte Reich direkt mit Orgrimmar und dem Basislager Grom'gol verbinden.",al={"wie bin ich hierher gekommen","wie bin ich nach tirisfal gekommen","wie bin ich angekommen"}},["89135166"]={q="Was soll ich in Tirisfal tun?",a="Euer Ziel ist es, den Verlassenen dabei zu helfen, ihren brüchigen Halt über die verseuchten Herzlande von Lordaeron zu sichern. Von den Krypten von Todesend in Richtung Brill müsst Ihr die gedankenlose Geißel ausmerzen, die verlassene Bauernhöfe heimsucht, die fanatischen Eiferer des The Scarlet Crusade ausschalten, die aus dem Norden vordringen, und die verseuchten Bestien ausdünnen, die durch die verrottenden Wälder streifen. Dies beweist Euren Wert für Fürstin Sylvanas und bereitet Euch darauf vor, ihrem wachsenden Königreich unter den Ruinen von Capital City zu dienen.",al={"was soll ich hier tun","warum bin ich in tirisfal","was ist mein ziel hier"}}},fp="15,338,18.442.0,19.456.0,26.372.0,42.269.0,65.287.0,53.289.0,39.222.0,53.244.0,53.247.0"}
P.entries["zone:undercity"] = {n="Unterstadt",s="Tief unter den zerschlagenen Ruinen der Hauptstadt von Lordaeron liegt Unterstadt, die dunkle Festung der Verlassenen. Ursprünglich von der Geißel aus uralten königlichen Krypten und Kerkern geschlagen, wurde sie von Fürstin Sylvanas Windläufer eingenommen und in eine uneinnehmbare unterirdische Zuflucht verwandelt. Heute dient sie als Sitz der Macht der Verlassenen und als lebenswichtige Bastion der Horde in den nördlichen Östlichen Königreichen.",h="Tief unter den zerschlagenen Ruinen der Hauptstadt von Lordaeron liegt Unterstadt, die dunkle Festung der...",kw={"das apothekarium","arthas","verlassene","lordaeron","geißel","sylvanas","terenas","tirisfal","unterstadt","varimathras"},ang={["faction:Horde"]="Als wichtigster Stützpunkt der Horde in den Östlichen Königreichen sichert Unterstadt direkte Zeppelinverbindungen zurück nach Durotar und in das Basislager Grom'gol.",["race:Human"]="Unter dem Boden Eures gefallenen angestammten Königreichs liegt eine düstere Verkehrung der königlichen Krypten von Lordaeron, besetzt von den wandelnden Leichen Eurer einstigen Brüder.",["race:Orc"]="Tief in diesen Verliesen war einst der legendäre Kriegshäuptling Orgrim Schicksalshammer von der Allianz von Lordaeron eingekerkert, ehe ihm seine historische Flucht gelang.",["race:Undead"]="Unterstadt ist Eure souveräne Zuflucht und Heimat, mit Euren eigenen Händen erbaut, nachdem Ihr den eisernen Griff des Lichkönigs über Euren Verstand gebrochen hattet."},sec={{t="Von königlichen Krypten zur Schanze der Geißel",b="Lange bevor die Seuche über Lordaeron hereinbrach, waren die Katakomben, Verliese und Abwasserkanäle unter dem Palast kollektiv als Unterstadt bekannt. Sie bargen die Gräber des Adels, die tiefsten Kerker des Königreichs – in denen der ehemalige Kriegshäuptling Orgrim Schicksalshammer einst vor seiner Flucht eingesperrt war – und die ärmsten Bewohner des Reiches. Als Arthas Menethil im Jahr 20 n. d. P. König Terenas ermordete und die Hauptstadt verwüstete, befahl der Prinz seinen untoten Dienern, die unterirdischen Gänge auszuheben und zu einem befestigten Herrschaftssitz der Geißel auszubauen."},{t="Aufstieg der Verlassenen",b="Die Geißel erlebte die Vollendung ihrer dunklen Hauptstadt nie. Als die Mächte des Lichkönigs nach der Schlacht um den Hyjal schwanden, riss sich Fürstin Sylvanas Windläufer vom Schwarmbewusstsein los und riss Tausende von Untoten mit sich. Sie lockte Arthas in einen Hinterhalt und trieb ihn nach Nordend zurück. Nach einem erbitterten Dreifronten-Bürgerkrieg gegen Überreste der Geißel, Schreckenslords und den menschlichen Widerstand beanspruchte Sylvanas die halbfertigen Katakomben für sich. Sie gab ihrem Volk den Namen die Verlassenen und leitete die jahrelangen Arbeiten zur Fertigstellung der weitläufigen unterirdischen Stadt."},{t="Architektur der Verdammten",b="Unterstadt ist in konzentrischen Ringen angelegt, die in funktionale Viertel unterteilt sind. In ihrem Herzen liegt das Handwerksviertel, das über gewaltige Aufzüge mit den Palastruinen darüber verbunden ist. Darum herum liegen das Kriegsviertel, das Schurkenviertel, das Magieviertel und das giftige Apothekarium, wo die Königliche Apothekervereinigung in von grünem Schleim gefüllten Kanälen bösartige Seuchen braut. Noch tiefer liegt das Königsviertel, wo die Bansheekönigin an der Seite ihres Schreckenslord-Kommandanten Varimathras Hof hält, bewacht von Legionen turmhoher Monstrositäten."}},faq={{q="Was war Unterstadt, bevor die Untoten sie übernahmen?",a="Unter dem Palast von Lordaeron lagen die uralten Krypten des menschlichen Königshauses sowie der Kerkerkomplex der Stadt und ein gewaltiges Kanalisationsnetz. Es beherbergte Kriegsgefangene, darunter Orgrim Schicksalshammer, sowie verarmte Bürger, die in den unterirdischen Schatten hausten. Nach der Plünderung der Hauptstadt begann Prinz Arthas, diese Katakomben in eine Festung der Geißel zu verwandeln, bevor Sylvanas sie eroberte.",al={"ursprünge von unterstadt","was war unterstadt ursprünglich","geschichte der kanalisation von lordaeron"}},{q="Warum wurde die Stadt unter der Erde erbaut statt an der Oberfläche?",a="Die oberirdische Stadt von Lordaeron wurde während des Dritten Krieges vollkommen zerstört, was eine Verteidigung gegen den Scharlachroten Kreuzzug, Streitkräfte der Geißel und Überlebende der Allianz erschwerte. Die unterirdischen Tunnel boten natürliche Befestigungen, Engpässe und Geheimhaltung, was es den Verlassenen ermöglichte, die ursprünglichen Bauarbeiten der Geißel zu vollenden und im Verborgenen zu gedeihen.",al={"warum unterirdisch leben","warum lordaeron nicht wiederaufbauen","warum unterstadt unter ruinen liegt"}},{q="Wer herrscht über Unterstadt?",a="Die Stadt wird von Fürstin Sylvanas Windläufer regiert, der Bansheekönigin und Königin der Verlassenen. Sie herrscht vom Königsviertel aus, bewacht von königlichen Wachen der Verlassenen und ihrem unterworfenen Schreckenslord-Leutnant Varimathras.",al={"wer ist anführer von unterstadt","herrscher von unterstadt","wer regiert unterstadt"}},{q="Was ist das Denkmal für König Terenas in den Ruinen darüber?",a="Über den Hauptaufzügen der Stadt befindet sich ein steinernes Denkmal für den ermordeten König Terenas Menethil II. Es enthält nicht seinen Leichnam, da dieser eingeäschert und seine Asche während Kel'Thuzads Wiedererweckung verstreut wurde. Überlebende Menschen der Allianz meißelten das Monument mutig inmitten der Ruinen, damit die Erinnerung an Lordaerons letzten wahren König fortbesteht.",al={"könig terenas grab","thronsaal grab lordaeron","wer baute das grab über unterstadt"}},{q="Was sind die seltsamen Geräusche im Thronsaal von Lordaeron?",a="Im zerstörten Thronsaal über den Aufzügen von Unterstadt hallen noch immer spektrale Echos der Vergangenheit nach. Besucher, die im Zentrum stehen, können leise Geistergeräusche vernehmen: die feierlichen Glocken und Rosenblüten bei Arthas' Rückkehr, die warnenden Worte des Propheten Medivh und das letzte Gespräch zwischen König Terenas und seinem vatermörderischen Sohn.",al={"geistergeräusche thronsaal","flüstern im thronsaal","stimmen im thronsaal von lordaeron"}},{q="Warum dulden die Verlassenen andere Mitglieder der Horde hier?",a="Die Verlassenen schlossen aus reinem Überlebenstrieb ein Zweckbündnis mit Kriegshäuptling Thralls Horde, umringt wie sie von feindseligen scharlachroten Eiferern und Legionen der Geißel waren. Obwohl lebende Völker der Horde die giftigen Dämpfe und alchemistischen Flüsse als erstickend empfinden, wird Abgesandten und Reisenden Zutritt gewährt, um diplomatische und militärische Bande zu pflegen.",al={"warum orcs in unterstadt sind","horde in unterstadt","warum unterstadt zur horde gehört"}}},fx={a590d153={q="Was ist die Unterstadt?",a="Die Unterstadt ist die unterirdische Hauptstadt der Verlassenen, die direkt unter den zerstörten Ruinen der Hauptstadt in Tirisfal erbaut wurde. Sie wurde aus alten königlichen Krypten, Abwasserkanälen und Katakomben herausgehauen und von Prinz Arthas als Festung der Geißel ausgebaut, bevor Fürstin Sylvanas Windläufer und ihre abtrünnigen Untoten sie während des Bürgerkriegs einnahmen. Heute dient sie als befestigter Zufluchtsort für Untote mit freiem Willen, durchzogen von giftigem Schlamm und wachsam bewacht gegen alle lebenden Eindringlinge.",al={"was ist die unterstadt","erzähl mir von der unterstadt","unterstadt hintergrundgeschichte"}},c51b16b2={q="Was geschah mit dem alten König von Lordaeron?",a="König Terenas Menethil II. wurde im Thronsaal direkt über dieser Stadt von seinem eigenen Sohn, Prinz Arthas, ermordet. Nachdem er aus Nordend zurückgekehrt war, verdorben durch die Runenklinge Frostgram, erschlug Arthas seinen Vater und ließ die Geißel über das Königreich hereinbrechen. Terenas' Asche wurde später vom Todesritter gestohlen, um Kel'Thuzad wiederzubeleben, wobei nur der Gedenkstein und die getrocknete Blutspur zurückblieben, die Ihr noch immer in der Nähe des zerstörten Throns sehen könnt.",al={"schicksal von könig terenas","was geschah mit könig terenas","wer tötete könig terenas"}},c11144c7={q="Wer war Arthas?",a="Arthas Menethil war der Kronprinz von Lordaeron und ein berühmter Paladin der Silbernen Hand. In seinem verzweifelten Versuch, die Plage des Untodes, die seine Heimat überrollte, aufzuhalten, wurde sein Kreuzzug rücksichtslos und fanatisch. In Nordend bemächtigte er sich der verfluchten Runenklinge Frostgram, die seine Seele verschlang und ihn zum schrecklichen Champion des Lichkönigs machte. Er kehrte nur nach Hause zurück, um seinen Vater abzuschlachten, Lordaeron dem Erdboden gleichzumachen und schließlich nach Norden zurückzukehren, um mit dem Frostthron zu verschmelzen.",al={"wer ist arthas","prinz arthas hintergrund","arthas menethil"}},["7f6bbd49"]={q="Wer ist Sylvanas Windläufer?",a="Fürstin Sylvanas Windläufer war einst die tapfere Waldläufergeneral von Silbermond, die Quel'Thalas während des Dritten Krieges gegen die Geißel verteidigte. Als sie fiel, riss Arthas ihre Seele aus ihrem Körper und verwandelte sie in eine Banshee, um sie zu quälen. Als der Griff des Lichkönigs schwächer wurde, brach sie frei, nahm ihre körperliche Form zurück und scharte andere unabhängige Untote um sich, die Verlassenen. Jetzt regiert sie als ihre Bansheekönigin vom Königsviertel aus.",al={"wer ist die bansheekönigin","sylvanas hintergrund","wer ist sylvanas"}},["2a8de90f"]={q="Warum wird Sylvanas die Dunkle Fürstin genannt?",a="Die Verlassenen ehren Sylvanas als die Dunkle Fürstin, weil sie sie aus der sinnlosen Knechtschaft des Lichkönigs befreit und ihnen Zuflucht gewährt hat, als der Rest von Azeroth nach ihrer totalen Ausrottung strebte. Der Beiname wird neben ihrem Titel als Bansheekönigin verehrt und spiegelt sowohl ihre schattenhafte Meisterschaft über den Tod als auch die wilde, unnachgiebige Hingabe ihrer untoten Untertanen wider.",al={"warum dunkle fürstin","titel dunkle fürstin sylvanas","bedeutung dunkle fürstin"}},["84f18f47"]={q="Warum sind die Verlassenen Teil der Horde?",a="Umgeben von feindseligen Scharlachroten Kreuzzüglern, der unerbittlichen Geißel und rachsüchtigen Überresten der Allianz, konnten die Verlassenen in Lordaeron nicht allein überleben. Fürstin Sylvanas nahm über das Meer Kontakt mit Kriegshäuptling Thrall auf und schmiedete ein pragmatisches Zweckbündnis. Die Horde gewann einen entscheidenden militärischen Stützpunkt in den Östlichen Königreichen, während die Verlassenen wesentliche Verstärkungen und politische Legitimität in ihrem Überlebenskampf sicherten.",al={"warum sind die verlassenen bei der horde","untote treten der horde bei","verlassene horde allianz"}},["71200045"]={q="Was ist die Geißel und sind sie noch in der Nähe?",a="Die Geißel ist die riesige, gefräßige Armee aus sinnlosen Untoten, die von der Brennenden Legion erschaffen wurde und vom Lichkönig aus Nordend regiert wird. Obwohl die Verlassenen die Unterstadt und Tirisfal ihrem Griff entrissen haben, bleibt die Geißel eine unmittelbare, tödliche Gefahr. Ihre Legionen unter dem Kommando von Kel'Thuzad ersticken noch immer die nahegelegenen Pestländer und befallen verlassene Gehöfte und Krypten in Tirisfal.",al={"ist die geißel in der nähe","was ist die geißel","geißel in lordaeron"}},["501548ab"]={q="Wo ist der Lichkönig jetzt?",a="Der Lichkönig residiert auf dem Frostthron in den fernen, eisigen Einöden von Nordend. Nach dem Bürgerkrieg in den Pestländern floh Prinz Arthas aus Lordaeron, um seinen schwächer werdenden Meister zu beschützen. Er bestieg den Gletscher und verschmolz ihre Essenzen zu einer einzigen schrecklichen Entität. Von dieser arktischen Bastion aus wacht sein eisiger Blick noch immer über Azeroth.",al={"wo ist der lichkönig","standort des lichkönigs","wo ist arthas jetzt"}},["4cc7f971"]={q="Wer ist der Scharlachrote Kreuzzug?",a="Der Scharlachrote Kreuzzug ist ein fanatischer Orden menschlicher Eiferer, der aus den Ruinen der Verteidigung von Lordaeron hervorgegangen ist. Geblendet von ihrem rechtschaffenen Hass auf die Untoten, unterscheiden sie nicht zwischen der sinnlosen Geißel und den Verlassenen mit freiem Willen. Sie betrachten jeden, der vom Untod gezeichnet ist – sowie jeden lebenden Außenseiter, der sie toleriert – als abscheuliche Kreaturen, die nur auf den Scheiterhaufen gehören. Ihre Hauptbastion in Tirisfal ist das Scharlachrote Kloster.",al={"wer ist der scharlachrote kreuzzug","scharlachrote kreuzzügler","scharlachroter kreuzzug hintergrund"}},["271820ed"]={q="Ist die Unterstadt gefährlich?",a="Sie ist außerordentlich gefährlich, besonders für Lebende. Kanäle mit rohen alchemistischen Abfällen und giftigem Schlamm durchziehen die Straßen der Stadt und füllen die höhlenartigen Hallen mit giftigen Dämpfen, die das Atmen für Besucher aus Fleisch und Blut gefährlich machen. Unter den gepflasterten Vierteln liegen verseuchte Abwasserkanäle, und noch tiefer finden geheime Experimente statt, bei denen täglich dunkle Alchemie und rücksichtslose Attentate geplant werden.",al={"ist die unterstadt sicher","gefahr in der unterstadt","gefahren in der unterstadt"}},["2539a3c3"]={q="Wie bin ich in der Unterstadt gelandet?",a="Als ein Verlassener führte Euer Weg Euch natürlich hierher, nachdem Ihr in Todesend aus dem Tod erwacht seid und Eure Loyalität in Tirisfal bewiesen habt, indem Ihr den Straßen vorbei an Brill gefolgt seid, um unter die zerstörten Ruinen der Hauptstadt hinabzusteigen. Wenn Ihr aus Kalimdor oder fernen Ländern stammt, seid Ihr wahrscheinlich an Bord eines Zeppelins der Horde angekommen, der an den Türmen direkt außerhalb der Hauptstadt anlegt, oder Ihr seid durch die verheerte Landschaft gewandert. Die Unterstadt ist der wichtigste Stützpunkt der Horde im nördlichen Lordaeron und bietet Schutz und Bestimmung unter den alten Palastkatakomben.",al={"wie bin ich hierher gekommen","wie erreiche ich die unterstadt","wie kommt man in die unterstadt"}},b63c4cf2={q="Was soll ich in der Unterstadt tun?",a="Ihr seid hier, um die Verlassenen zu unterstützen und die Stärke der Horde gegen die Gefahren zu versammeln, die Lordaeron umgeben. Innerhalb der konzentrischen Viertel der Stadt könnt Ihr Klassenlehrer aufsuchen, Vorräte erwerben und die dunklen Forscher der Royal Apothecary Society konsultieren. Jenseits Eures Handwerks ist es Eure Pflicht, Aufträge für Fürstin Sylvanas Windläufer und ihre Leutnants anzunehmen. Die Verlassenen führen einen Krieg an mehreren Fronten: die Überreste der sinnlosen Geißel säubern, den fanatischen Scharlachroten Kreuzzug zurückschlagen und sicheren Boden für die Untoten mit freiem Willen sichern, damit sie überdauern können.",al={"was mache ich hier","was soll ich in der unterstadt tun","warum bin ich hier"}}},fp="9,318,36.556.0,20.416.0,26.421.0,54.450.0,60.340.0,24.362.0,51.333.0,57.328.0,51.322.0"}
P.entries["zone:ungoro"] = {n="Krater von Un'Goro",s="Der Krater von Un'Goro ist ein versunkener, urzeitlicher Dschungel, der zwischen den trockenen Einöden von Tanaris und Silithus eingebettet liegt. Beherrscht von umherstreifenden Dinosauriern, lebenden Elementaren und einem zentralen Vulkan, ist diese üppige Caldera reich an uralten Titanenrelikten und Machtkristallen, deren Ursprünge ein tiefes Geheimnis bleiben.",h="Der Krater von Un'Goro ist ein versunkener, urzeitlicher Dschungel, der zwischen den trockenen Einöden von...",kw={"teufelssaurier","feuersäulengrat","goetterlaender","lakkari","marschalls zuflucht","machtkristalle","torwa pfadfinder","ungoro","krater von ungoro"},ang={["class:Druid"]="Druiden des Zirkels des Cenarius erforschen Un'Goros isoliertes Ökosystem und ernten seine fruchtbare Erde, um Morgenkorn zu vermehren, mit dem Ziel, die reine, ungezähmte Lebenskraft zu verstehen, die die Caldera speist.",["faction:Alliance"]="Naturforscher der Allianz sammeln sich um Williden Marschall und J.D. Collie in Marschalls Zuflucht und wetteifern darum, die Pylonen der Titanen zu entschlüsseln, während sie gleichzeitig Darnassus-Forscher beim Sammeln von Bodenproben beschützen.",["faction:Horde"]="Abenteurer der Horde reisen oft über Tanaris an, um ihr Können an legendären Teufelssauriern zu messen und den Kräuterkundigen von Donnerfels dabei zu helfen, Morgenkorn aus Un'Goros urzeitlicher Erde zu züchten.",["profession:Herbalism"]="Die reiche Feuchtigkeit des Beckens erhält seltene Flora und macht es zu einem der wenigen Orte in Kalimdor, an denen Erdenwurzel, Traumblatt und Goldener Sansam zusammen mit der Feuerblüte an den Hängen des Vulkans gedeihen.",["profession:Mining"]="Die steilen Kraterwände und die Felsen des Feuersäulengrats sind dicht mit Mithrilvorkommen und Reichen Thoriumadern besetzt, was die Zone zu einem erstklassigen Ziel für hochwertige Erze macht."},sec={{t="Die Götterländer",b="Eingebettet zwischen Wüstenweiten trotzt der Krater von Un'Goro der Geographie des südlichen Kalimdor. Uralte Aufzeichnungen der Nachtelfen über den Krieg der Sandstürme belegen, dass die insektoiden Qiraji an den Rändern des Kraters zurückgeschlagen wurden, unfähig, in das vorzudringen, was ihre Sprache als die „Götterländer“ bezeichnete. Gelehrte stellen Theorien auf, wonach die Caldera den Titanen während der Formung von Kalimdor als Testgelände oder uralte Wohnstätte diente. Entlang der Grate erheben sich steinerne Pylonen, die vor Energie summen, während Kristallformationen in Blau, Rot, Grün und Gelb aus der urzeitlichen Erde sprießen."},{t="Ein wildes Ökosystem",b="Un'Goro beherbergt keine Städte, Dörfer oder einheimische humanoide Gesellschaften. Stattdessen gedeiht das Leben in einem ungezähmten, urzeitlichen Zustand. Spitzenprädatoren wie Teufelssaurier durchstreifen die Weiten der Terrorflucht, räuberische Blutblüten peitschen in den Marschen um sich, und Schleime kriechen über die Teergruben von Lakkari. Im Herzen des Kraters ragt der Feuersäulengrat empor, ein aktiver Vulkangipfel voller feindseliger Feuerelementare, angeführt von dem Wesen Feuerläufer. Für Entdecker und Kürschner bietet das Becken einen unübertroffenen natürlichen Reichtum – einschließlich der begehrten Bälge von Teufelssauriern –, vorausgesetzt, man überlebt die Nahrungskette."},{t="Marschalls Zuflucht",b="Die zivilisierte Präsenz im Krater beschränkt sich fast ausschließlich auf Marschalls Zuflucht, ein erhöhtes Lager in den nördlichen Klippen. Angeführt von Williden Marschall versuchte eine Expedition aus Wissenschaftlern, Naturforschern und Glückssuchern, die Schätze des Beckens zu katalogisieren, nur um von der monströsen Tierwelt heimgesucht und auf höher gelegenes Gelände vertrieben zu werden. Heute dient die Zuflucht als umkämpfter Stützpunkt für unerschrockene Reisende, die die geheimnisvollen Machtkristalle des Kraters studieren, die vulkanische Aktivität kartieren und ein wachsames Auge auf die vordringenden Silithidenschwärme haben, die die südlichen Grate durchbrechen."}},faq={{q="Wie gelangt Ihr in den Krater von Un'Goro?",a="Reisende können über natürliche Rampen hinabsteigen, die die Kraterwände hinunterführen: Eine ist von der südwestlichen Ecke von Tanaris nahe dem Disteltal aus zugänglich, eine andere führt aus dem nordöstlichen Silithus hinein. Während waghalsige Abenteurer zuweilen die Klippen hinabspringen, endet der Sturz ohne magische Unterstützung tödlich. Marschalls Zuflucht im Norden bietet Flugverbindungen nach Gadgetzan und Burg Cenarius.",al={"wie man ungoro betritt","ungoro eingang","wie man den krater von ungoro erreicht"}},{q="Wofür werden die farbigen Machtkristalle verwendet?",a="Über den Dschungelboden verstreut liegen rote, blaue, grüne und gelbe Machtkristalle. Unter Anleitung der Gnomforscherin J.D. Collie in Marschalls Zuflucht können Forscher Anweisungen zur Nutzung dieser Kristalle am Nördlichen, Östlichen und Westlichen Pylon entschlüsseln. Die Kombination bestimmter Farben an den entsprechenden Pylonen nutzt latente Titanenenergien, um schützende oder wiederherstellende Talismane herzustellen.",al={"ungoro kristalle","rote blaue gruene gelbe kristalle ungoro","machtpylonen"}},{q="Warum ist Un'Goro trotz der umgebenden Wüsten so üppig?",a="Gelehrte glauben, dass Un'Goros unnatürliche Lebenskraft künstlich ist und von den Titanen herrührt, die die Welt formten. Titanische Leitungen, warme vulkanische geothermische Aktivität vom Feuersäulengrat und uralte Ley-Energie nähren ein isoliertes, extrem beschleunigtes Ökosystem, das den ariden Bedingungen des benachbarten Tanaris und Silithus trotzt.",al={"warum ist ungoro ein dschungel","ungoro wuesten verbindung","wie hat ungoro pflanzen"}},{q="Warum nannten die Qiraji diesen Ort die „Götterländer“?",a="Laut Tafeln, die aus dem Krieg der Sandstürme übersetzt wurden, hielten die Insektenschwärme ihren Vormarsch an der Schwelle des Kraters an. Geologe Larksbane, der den Bericht übersetzte, verknüpft den Namen mit Theorien, wonach die Titanen einst im Krater weilten, und fragt sich, ob Aman'Thul selbst über die Götterländer wachte.",al={"goetterlaender bedeutung","qiraji ungoro","warum konnten die silithiden ungoro nicht einnehmen"}},{q="Wofür wird Un'Goro-Erde verwendet?",a="Haufen fruchtbarer, wirkmächtiger Erde liegen im gesamten Kraterbecken. Nach der Ernte kann diese Erde mit Tharlendris-Samen in einem Immergrünbeutel kombiniert werden, um Morgenkorn heranzuzüchten – ein mystisches Kraut, das von Forschern in Donnerfels, Darnassus und dem Zirkel des Cenarius heiß begehrt wird.",al={"ungoro erdenprobe","was bewirkt ungoro erde","morgenkorn erde"}},{q="Gibt es hier humanoide Siedlungen oder Dungeons?",a="Der Krater von Un'Goro beherbergt einen Dungeon, Die Terrasse des Formers, für etwa die Stufen 58 bis 60, aber keine einheimischen humanoiden Gesellschaften. Die einzige dauerhafte Siedlung ist Marschalls Zuflucht, ein kleiner Expeditionsaußenposten am nördlichen Rand. Abgesehen von vereinzelten Einsiedler-Jägern oder verirrten Forschern ist der Rest der Caldera vollkommen wild.",al={"ungoro dungeons","wer lebt in ungoro","humanoide in ungoro"}}},fp="14,269,13.410.0,18.462.0,16.490.0,35.282.0,45.336.0,56.270.0,51.330.0,30.235.0,52.287.0"}
P.entries["zone:wailing"] = {n="Die Höhlen des Wehklagens",s="Verborgen unter Der blühenden Oase im dürren Brachland liegen Die Höhlen des Wehklagens, ein labyrinthisches System unterirdischer Quellen und Klüfte, benannt nach dem unheimlichen Pfeifen des eingeschlossenen Dampfes. Was als edles druidisches Bestreben begann, Kalimdors sonnengebleichte Savanne wiederzubeleben, hat sich zu einer verzerrten, giftigen Unterwelt entwickelt. Die Höhlen wimmeln nun von entstellter Tierwelt und gefallenen Jüngern, die von einem tiefen, unnatürlichen Alptraum korrumpiert wurden.",h="Verborgen unter Der blühenden Oase im dürren Brachland liegen Die Höhlen des Wehklagens, ein labyrinthisches...",kw={"deviat","druiden des giftzahns","smaragdgrüner alptraum","lady anakondra","lord kobrahn","lord pythas","lord serpentis","die blühende oase","mutanus","naralex","verdan"},ang={["class:Druid"]="Für Druiden sowohl der Tradition des Cenarius als auch des Pfades der Tauren sind die Höhlen eine tragische Warnung vor den Gefahren im Smaragdgrünen Traum und eine feierliche Pflicht, ihre gefallenen Brüder, die Druiden des Giftzahns, zu läutern.",["race:NightElf"]="Naralex war eine verehrte Persönlichkeit unter den Nachtelfen-Druiden, und die Tragödie seiner Korrumpierung durch den Smaragdgrünen Alptraum stellt eine schmerzhafte Katastrophe für sein Volk jenseits des Meeres dar.",["race:Tauren"]="Die vergifteten Gewässer bedrohen die zerbrechlichen Oasen, die das Leben im gesamten Brachland erhalten, weshalb die Reinigung der Quellen für die Stämme von Mulgore und Das Wegekreuz von entscheidender Bedeutung ist."},sec={{t="Eine edle Vision wird giftig",b="Der Nachtelfen-Druide Naralex entdeckte ursprünglich dieses gewaltige Wassersystem und fasste einen ehrgeizigen Plan: Indem er einen Kanal direkt in Den Smaragdgrünen Traum öffnete, wollte er reine, urtümliche Lebensessenz durch die unterirdischen Quellen leiten und das ausgedörrte Brachland wieder in ein blühendes, fruchtbares Paradies verwandeln. Tief in den Höhlen versank Naralex in Trance zur Zwiesprache mit dem Traum, verankert durch seine treuen Akolythen. Tragischerweise berührte der schlafende Geist des Druiden, anstatt reine Vitalität anzuzapfen, den Smaragdgrünen Alptraum. Die schwärende Verderbnis ergriff sofort Besitz von ihm und verwandelte seinen wohlmeinenden Kanal in ein Ventil, das Gift und Wahnsinn in die unterirdischen Wasserwege goss."},{t="Die Druiden des Giftzahns",b="Als die dunkle Energie des Alptraums von Naralex' hilfloser Gestalt ausstrahlte, erlagen seine Schüler dem Wahnsinn. Sie sagten sich von der friedvollen Weisheit des Zirkels des Cenarius los und gründeten die fanatischen Druiden des Giftzahns. Die Anführer der Sekte – Lady Anakondra, Lord Kobrahn, Lord Pythas und Lord Serpentis – nahmen reptilienartige Gestalten an und nahmen die giftige Mutation der Höhlen an, anstatt sie zu bekämpfen. Sie schirmen ihren schlafenden Meister aktiv vor jeglicher Einmischung von außen ab, im Glauben, dieses entstellte Wachstum sei die wahre Evolution der Natur."},{t="Der fleischgewordene Alptraum",b="Den Griff der Druiden des Giftzahns zu brechen, rettet Naralex nicht automatisch. Wenn seine verbliebenen, unkorrumpierten Jünger am Dreamer's Rock das Ritual einleiten, um ihn sanft aus seiner Trance zu wecken, stößt das sich windende Unterbewusstsein des schlummernden Elfen gewaltsam seinen tiefsten Schrecken aus. Die Kreatur, die daraus hervorbricht – ein monströser, entstellter Murloc namens Mutanus der Verschlinger –, ist die physische Manifestation von Naralex' schlimmsten Alpträumen. Nur durch das Erschlagen dieser Abscheulichkeit kann die Verbindung zum Alptraum gekappt werden, was Naralex ermöglicht zu erwachen, die Gestalt eines Vogels anzunehmen und aus den besudelten Höhlen zu fliehen."}},faq={{q="Warum heißen sie Die Höhlen des Wehklagens?",a="Die Höhle verdankt ihren Namen den klagenden, heulenden Schreien, die in den gesamten Tunneln zu hören sind. Diese Geräusche entstehen auf natürliche Weise, wenn unterirdische Dampfschlote und unter hohem Druck stehende Windstöße ihren Weg durch enge Klüfte im Kalksteinfelsen erzwingen.",al={"warum höhlen des wehklagens","ursprung des namens","warum wehklagen sie"}},{q="Was ließ die Bestien im Inneren zu 'Deviat'-Kreaturen werden?",a="Als Naralex dem Einfluss des Smaragdgrünen Alptraums verfiel, drangen die verdorbenen Traumenergien direkt in die unterirdischen Quellen ein. Das Trinken und Leben in diesen kontaminierten Gewässern mutierte die natürlichen Raptoren, Krokilisken und Schlangen zu unnatürlichen 'Deviat'-Varianten.",al={"deviatverderbnis","warum mutieren raptoren","ursprung der deviatbestien"}},{q="Wer sind die Druiden des Giftzahns?",a="Sie waren einst die hingebungsvollen Nachtelfen- und Tauren-Akolythen von Naralex. Gemeinsam mit ihm durch den Alptraum korrumpiert, zerbrach ihr Verstand und verdrehte ihre druidischen Künste zur Verehrung von Schlangen und Gift, wobei sie Titel wie Kobrahn, Pythas und Anakondra annahmen.",al={"giftzahnrudiden","druiden des giftzahns lore","wer ist serpentis"}},{q="Warum ist der Endboss ein riesiger Murloc namens Mutanus?",a="Mutanus erscheint während des Versuchs, Naralex zu erwecken. Sein Wesen und seine Verbindung zum schlafenden Druiden offenbaren sich im Verlauf des Rituals.",al={"warum mutanus murloc","was ist mutanus","endboss lore"}},{q="Was geschieht, nachdem Mutanus besiegt ist?",a="Der Versuch der Jünger, Naralex zu erwecken, geht nach der Konfrontation weiter. Das Schicksal des Druiden offenbart sich am Ende des Rituals.",al={"naralex erwecken","naralex ende","was geschieht mit naralex"}},{q="Wer lebt in der Höhle über dem Höhleneingang?",a="In der totenkopfartigen Felsenaugenhöhle über den Höhlen haben sich Getreue des Zirkels des Cenarius niedergelassen, darunter Nalpak und Ebru. Sie suchen mutige Reisende, um Deviatbälge zu erbeuten und die Verderbnis zu reinigen, bevor sie das Brachland vollständig verschlingt.",al={"höhle über eingang","schlangenschädel auge npcs","wer sind nalpak und ebru"}}},fx={["38e519c2"]={q="Warum macht sich jeder solche Sorgen um diesen Ort?",a="Die unterirdischen Quellen in den Höhlen speisen die primären Oasen, die das Leben im ariden Brachland erhalten. Sollte der Makel des Smaragdgrünen Traums ungehindert in diese Wasserwege sickern, könnten sich die verdrehten Mutationen und der Wahnsinn, die die Flora und Fauna der Höhlen korrumpieren, über die gesamte Region ausbreiten und das Land in einen Albtraum bei Tageslicht verwandeln.",al={"warum sorgen um die höhlen des wehklagens","die höhlen des wehklagens bedrohung für das brachland","wie schlimm sind die höhlen des wehklagens"}},["81917ac6"]={q="Wie bin ich in den Höhlen des Wehklagens gelandet?",a="Ihr seid vom Wegekreuz nach Süden in Die blühende Oase gereist, den Berichten über bizarre Bestien und korrumpiertes Wasser folgend, das durch das Brachland sickerte. Hinter dem üppigen Blattwerk und den Lagern der Kolkar-Zentauren liegt eine gewaltige, schädelförmige Höhle, die in den Fels gehauen wurde. Angelockt durch Hilferufe aus Donnerfels, durch Goblins aus Ratschet, die nach seltsamen Essenzen suchten, oder durch Jünger, die im Auge des Schädels oben kampierten, seid Ihr an den gewundenen Spalten und dem Zischen unterirdischer Geysire vorbei in die stöhnenden Tiefen hinabgestiegen.",al={"wie bin ich hierher gekommen","wie erreiche ich die höhlen des wehklagens","woher bin ich hierher gekommen"}},["28a012f3"]={q="Was soll ich in den Höhlen des Wehklagens tun?",a="Ihr seid hier, um die Korruption zu tilgen, die diese unterirdische Quelle befallen hat. Der Nachtelf-Druide Naralex fiel in einen albtraumhaften Schlaf, als er versuchte, das Brachland wiederzubeleben, was die Kreaturen darin verdrehte und seine Jünger in die giftigen Druiden des Giftzahns verwandelte. Ihr müsst die vier Giftzahnfürsten – Lady Anakondra, Lord Kobrahn, Lord Pythas und Lord Serpentis – zur Strecke bringen, um ihren Griff zu brechen, und dann den verbliebenen Jüngern helfen, Naralex zu wecken, bevor sein fiebriger Albtraum die Oase vollständig verschlingt.",al={"was ist mein ziel hier","warum bin ich in den höhlen des wehklagens","was mache ich hier unten"}},["3386ab3f"]={q="Was sind Die Höhlen des Wehklagens?",a="Die Höhlen des Wehklagens sind ein weitläufiges unterirdisches Höhlensystem, das unter dem trockenen Brachland, nahe der blühenden Oase, verläuft. Seine natürlichen unterirdischen Quellen leiten Wasser kilometerweit unter der Erde und speisen die seltenen Oasen an der Oberfläche, die über die Region verstreut sind. Entdeckt von dem Nachtelf-Druiden Naralex, sollten sie das Herz eines großen Projekts zur natürlichen Regeneration werden. Stattdessen wurden sie zu einem Epizentrum gefährlicher Verderbnis, nachdem eine tragische Katastrophe die Druiden darin ergriffen hatte.",al={"was sind die höhlen des wehklagens","übersicht der höhlen des wehklagens","über die höhlen des wehklagens"}},e070a543={q="Wer lebt dort unten?",a="Die Höhlen wimmeln von unnatürlicher Tierwelt und abtrünnigen Druiden. Naralex' korrumpierte Anhänger, die Leaders of the Fang, haben die Tunnel zusammen mit mutierten Schlangen, Schlämmen, Raptoren und Krokilisken als ihr Gebiet beansprucht. Außerhalb des Instanzeingangs lauern wilde Bestien, Schlämme und sogar Ausgestoßene in den feuchten Gängen, während die korrumpierten Druiden die inneren Kammern bewachen und ihren schlafenden Meister beschützen.",al={"wer ist in den höhlen des wehklagens","kreaturen in den höhlen des wehklagens","bewohner der höhlen des wehklagens"}},["49d47201"]={q="Warum hat mich die Horde hierher geschickt?",a="Die seltsamen Mutationen der einheimischen Bestien und die faulen Energien, die aus der blühenden Oase sprudeln, bedrohen das gesamte Brachland. Die Horde und die Cenarion-Druiden von Donnerfels können es nicht dulden, dass eine unkontrollierte dunkle Macht das Land und die Wasserwege direkt vor der Haustür des Wegekreuzes vergiftet. Ihr wurdet ausgesandt, um Nachforschungen anzustellen, den abtrünnigen Leaders of the Fang ein Ende zu bereiten und dabei zu helfen, die wachsende Gefahr zu unterdrücken.",al={"warum bin ich in den höhlen des wehklagens","mission der horde in den höhlen des wehklagens","warum hat man mich in die höhlen des wehklagens geschickt"}},d445bb78={q="Ist das Teil eines größeren Problems im Brachland?",a="Ja. Die unterirdischen Kanäle unter diesen Höhlen speisen die Oasen an der Oberfläche im gesamten Brachland. Die Verderbnis des Alptraums, die das Wasser in den Höhlen korrumpiert, hat begonnen, in die umliegende Landschaft überzulaufen, was dazu führt, dass wilde Kreaturen wie Raptoren und Krokilisken mutieren und die blühende Oase in eine Brutstätte für seltsames Deviatleben verwandelt.",al={"problem mit den oasen im brachland","deviatverderbnis im brachland","beeinflussen die höhlen des wehklagens das brachland"}},["038fd1cf"]={q="Breiten sich die Deviatwesen außerhalb der Höhlen aus?",a="Das tun sie bereits. Die unterirdischen Quellen fließen direkt in oberirdische Oasen wie die blühende Oase und bringen unnatürliches Wachstum und mutierte Kreaturen in die offene Savanne. Seltsame Kreaturen wie Deviatfisch können aus den Gewässern außerhalb gefischt werden, und aggressive mutierte Raubtiere belästigen zunehmend Reisende zwischen den Oasen und dem Wegekreuz.",al={"breiten sich die deviatwesen aus","deviatbestien im brachland","deviatfisch außerhalb"}},["8502642f"]={q="Wer hat hier das Sagen?",a="Während Naralex tief in den Höhlen in seinem korrumpierten Schlummer gefangen liegt, gehört die tägliche Herrschaft über die Höhlen den Druiden des Giftzahns. Sie werden von Lord Serpentis angeführt, einst Naralex' bester Schüler, der seine verdrehten Brüder versammelte, um das Land in ihr eigenes verzerrtes Paradies zu verwandeln, zusammen mit anderen fang lords wie Cobrahn, Pythas und Lady Anakondra.",al={"wer führt die höhlen des wehklagens","anführer der höhlen des wehklagens","boss der höhlen des wehklagens"}},["32be29c8"]={q="Was ist der Smaragdgrüne Traum und wie hängt er mit dieser Höhle zusammen?",a="Der Smaragdgrüne Traum ist ein riesiges Geisterreich, das Azeroth unberührt und wild darstellt, von dem grünen Drachenschwarm behütet und für Druiden zugänglich. Naralex glaubte, er könne die reinen, wiederherstellenden Energien des Traums in die unterirdischen Aquifere der Höhlen des Wehklagens leiten, um üppiges Pflanzenleben im Brachland wiederherzustellen. Als er ihn jedoch anzapfte, wurde er vom Smaragdgrünen Alptraum gefangen genommen, was eine verdrehte Version der Natur in die physischen Höhlen projizierte.",al={"verbindung zum smaragdgrünen traum","höhlen des wehklagens smaragdgrüner traum","naralex smaragdgrüner traum"}}},fp="15,278,31.501.0,22.495.0,24.481.1,37.218.0,50.226.0,31.267.0,51.127.1,39.123.1,52.229.0"}
P.entries["zone:warsonggulch"] = {n="Kriegshymnenschlucht",s="Die Kriegshymnenschlucht ist ein bewaldetes Tal an der Grenze zwischen dem Eschental und dem Brachland und Schauplatz eines Kampfes zwischen Horde und Allianz, der niemals wirklich endet. Orcs des Kriegshymnenklans schlagen dort für die Horde Holz im Eschental, während die Nachtelfen der Feste Silverwing sie aus dem heiligen Wald zu vertreiben versuchen. Kämpfer aller Völker kommen, um mit Schwert oder Zauber beizustehen; jede Seite überfällt die Festung der anderen, um deren Flagge zu erbeuten.",h="Die Kriegshymnenschlucht ist ein bewaldetes Tal an der Grenze zwischen dem Eschental und dem Brachland und...",kw={"kriegshymnenschlucht","schlachtfeld","vorhut des kriegshymnenklans","schildwachen der silberschwingen","feste silverwing","warsong mill","flagge","holz","eschental","grom hellscream"},ang={["faction:Alliance"]="Soldaten der Allianz kämpfen hier für ihre Nachtelfenverbündeten, deren heiliger Wald Baum für Baum den Äxten des Kriegshymnenklans zum Opfer fällt.",["faction:Horde"]="Jeder Baumstamm, der die Warsong Mill verlässt, errichtet irgendwo in Kalimdor eine Mauer der Horde; das Halten der Schlucht sichert den Aufbau der Horde.",["race:NightElf"]="Diese Wälder kennen die Schritte der Kaldorei seit zehntausend Jahren. Jeder aus der Schlucht vertriebene Orc ist ein Stück zurückgewonnenes Eschental.",["race:Orc"]="Der Kriegshymnenklan ist Grom Hellscreams eigenes Volk, und in der Schlucht verdienen sich seine Krieger noch immer ihren Namen, mit der Axt in der Hand gegen die Schildwachen."},sec={{t="Holz und Blut",b="Die Horde baute ihre neue Heimat in Kalimdor aus Holz, und ein Großteil dieses Holzes stammt aus dem Eschental. Der Kriegshymnenklan, Grom Hellscreams Krieger, dringt seit der ersten Landung der Horde in den Wald vor, und ihre Warsong Mill am Ende der Schlucht versorgt die Lager und Mauern der Horde. Für die Nachtelfen verwundet jeder gefällte Baum einen Wald, den sie seit zehntausend Jahren behütet haben, und sie haben nicht vergessen, dass Groms Krieger einst Cenarius in diesen Wäldern erschlugen."},{t="Vorhut und Schildwachen",b="Die Kämpfer der Horde sind hier die Vorhut des Kriegshymnenklans. Sie werden vom Mor'shan-Stützpunkt am nördlichen Rand des Brachlands versorgt, wo Kelm Hargunth sie bewaffnet und verpflegt. Ihnen stellen sich die Schildwachen der Silberschwingen aus der Feste Silverwing entgegen, Nachtelfenkrieger, die geschworen haben, jeden Eindringling aus dem Eschental zu vertreiben. Illiyana Mondflamm versorgt sie vom Hain der Silberschwingen aus. Verbündete beider Seiten strömen in die Schlucht: Zwerge und Menschen stehen den Schildwachen bei, Tauren, Trolle und Verlassene der Vorhut."},{t="Der Kampf um die Banner",b="Jede Seite hält an einem Ende der Schlucht eine Festung: die Kriegshymnenmühle für die Horde und die Feste Silverwing für die Nachtelfen. Dort bewahrt jede Seite ihre Standarte auf. Die Schlacht ist ein Wettstreit um Überfälle: Kämpfer dringen in die feindliche Festung ein, ergreifen deren Flagge und eilen damit zu ihrer eigenen zurück, während die Verteidiger sie verfolgen. Jede heimgebrachte Flagge ist ein Schlag gegen den Stolz des Feindes, und die Seite, die die meisten erbeutet, gewinnt den Tag."}},faq={{q="Was ist die Kriegshymnenschlucht?",a="Die Kriegshymnenschlucht ist ein Schlachtfeld in einem bewaldeten Tal zwischen dem Eschental und dem Brachland. Die Vorhut des Kriegshymnenklans der Horde und die Schildwachen der Silberschwingen der Nachtelfen kämpfen dort um den Holzschlag der Horde im Eschental, wobei jede Seite versucht, die Flagge der anderen zu erobern.",al={"was ist die kriegshymnenschlucht","kriegshymnenschlucht schlachtfeld","wsg"}},{q="Warum kämpft die Horde in der Kriegshymnenschlucht?",a="Die Horde benötigt das Holz des Eschentals, um ihre Heimat in Kalimdor aufzubauen und zu behaupten. Die Sägemühle des Kriegshymnenklans an der Schlucht ist eine ihrer Hauptquellen, und die Vorhut verteidigt sie, damit die Lager und Mauern der Horde weiter wachsen.",al={"horde ziele kriegshymnenschlucht","warum schlagen die orcs holz im eschental","vorhut des kriegshymnenklans beweggrund"}},{q="Warum kämpfen die Nachtelfen in der Kriegshymnenschlucht?",a="Für die Nachtelfen ist das Eschental ein heiliger Wald, den sie seit zehntausend Jahren behütet haben, und der Kriegshymnenklan erschlug dort einst den Halbgott Cenarius. Die Schildwachen der Silberschwingen kämpfen darum, den Holzschlag zu stoppen und die Orcs aus ihren Wäldern zu vertreiben, und der Rest der Allianz steht ihnen zur Seite.",al={"allianz ziele kriegshymnenschlucht","warum kaempfen die schildwachen","schildwachen der silberschwingen beweggrund"}},{q="Wer ist die Vorhut des Kriegshymnenklans?",a="Die Vorhut des Kriegshymnenklans sind die Kämpfer der Horde in der Kriegshymnenschlucht, gestellt vom einst von Grom Hellscream angeführten Kriegshymnenklan. Sie werden vom Mor'shan-Stützpunkt im nördlichen Brachland aus versorgt, wo Kelm Hargunth jene ausrüstet, die für sie kämpfen.",al={"vorhut des kriegshymnenklans","kriegshymnenklan kaempfer","kelm hargunth"}},{q="Wer sind die Schildwachen der Silberschwingen?",a="Die Schildwachen der Silberschwingen sind Nachtelfenkrieger der Feste Silverwing, die geschworen haben, die Horde aus dem Eschental zu vertreiben. Illiyana Mondflamm im Hain der Silberschwingen versorgt die Champions der Allianz, die ihnen in der Schlucht beistehen.",al={"schildwachen der silberschwingen","feste silverwing","illiyana mondflamm"}},{q="Wie wird die Schlacht in der Kriegshymnenschlucht gewonnen?",a="Jede Seite bewahrt ihre Flagge in ihrer eigenen Festung auf. Kämpfer überfallen den Stützpunkt des Feindes, ergreifen dessen Flagge und tragen sie zu ihrer eigenen zurück, während sie ihr eigenes Banner verteidigen, und die Seite, die die meisten Flaggen heimbringt, gewinnt.",al={"kriegshymnenschlucht ziele","flagge erobern kriegshymne","kriegshymnenschlucht gewinnen"}}},fp="13,291,16.424.0,23.488.0,28.315.0,22.226.0,42.201.0,46.259.0,30.223.0,33.216.0,39.193.0"}
P.entries["zone:westernplaguelands"] = {n="Westliche Pestländer",s="Einst die fruchtbare landwirtschaftliche Kornkammer des nördlichen Lordaeron, ersticken die Westlichen Pestländer nun unter giftigem Nebel und Legionen von Untoten. Obwohl Kel'Thuzads Kessel die Höfe und Städte der Region ruinierten, klammert sich der Boden immer noch hartnäckig an das Leben. Die Argentumdämmerung, die Allianz, die Verlassenen und der Scharlachrote Kreuzzug führen allesamt verzweifelte Feldzüge auf ihren verseuchten Feldern.",h="Einst die fruchtbare landwirtschaftliche Kornkammer des nördlichen Lordaeron, ersticken die Westlichen...",kw={"andorhal","das bollwerk","darrowehr","kessel","zugwindlager","herdweiler","burg mardenholde","scholomance","uthers grabmal","westliche pestländer"},ang={["class:Paladin"]="Die entweihten Felder Lordaerons stellen eine düstere Prüfung für heilige Krieger dar; sie bieten Pilgerfahrten zu Uthers Grabmal ebenso wie einen gerechten Krieg gegen die Schrecken von Scholomance und Herdweilers verderbte Fanatiker.",["faction:Alliance"]="Das Zugwindlager dient als vorderste Garnison der Allianz, von wo aus Kommandant Ashlam Faustwacht Feldzüge leitet, um die Pestkessel zu stören und die gefallenen Städte Lordaerons zu rächen.",["faction:Horde"]="Das Bollwerk markiert die Grenze der Souveränität der Verlassenen; von hier aus stößt die Horde nach Osten vor, um Kommandanten der Geißel auszuschalten und scharlachrote Fanatiker an ihrer verwundbaren Flanke zu bekämpfen.",["profession:Herbalism"]="Die verbliebene Verderbnis macht die Region zu einem der wenigen Orte, an denen seltene, gefährliche Pflanzen wie Pestblüte und Arthas' Tränen zwischen verseuchten Kiefernhainen Wurzeln schlagen können."},sec={{t="Die Kornkammer von Lordaeron",b="Vor dem Dritten Krieg war dieses Land ein saftig grüner Korridor aus Bauernhöfen, der sich von Tirisfal ostwärts in Richtung des Darrowmeresees erstreckte. Herdweiler leitete die nördliche Verwaltung von Burg Mardenholde aus, während die weitläufige Stadt Andorhal die Lagerung und den Export von Getreide im gesamten Königreich koordinierte. Diese entscheidende landwirtschaftliche Rolle machte die Region zu Kel'Thuzads Hauptziel. Indem der Kult der Verdammten die Seuche des Untods direkt in die Getreidelieferungen in Andorhal einschleuste, verwandelte er Lordaerons Lebensgrundlage in seinen Untergang."},{t="Ein Land unter Belagerung",b="Um den Boden dauerhaft zu vergiften, errichtete die Geißel vier gewaltige Pestkessel auf den größten landwirtschaftlichen Gütern: Teufelssteinfeld, Dalsons Tränenfeld, Das trostlose Feld und Gahrrons Trauerfeld. Heute warten monströse Kessellords diese giftigen Bottiche, die giftigen Nebel in die Atmosphäre pumpen. Die umliegenden Bäume winden sich vor geschwollenen, tumorartigen Wucherungen, und verseuchte Wildtiere wüten durch das Dickicht. Unterhalb von Darrowehr auf dem Darrowmeresee bildet Dunkelmeister Gandling innerhalb von Scholomance Nekromanten aus und verstärkt so die untote Bedrohung."},{t="Gespaltene Fraktionen",b="Trotz der Omnipräsenz der Geißel halten mehrere Fraktionen umkämpfte Stützpunkte. Der Scharlachrote Kreuzzug kontrolliert die Festung Herdweiler im Norden und läutert mit fanatischem Eifer alles, was er für verdorben hält. Im Süden sammeln sich die Streitkräfte der Allianz im Zugwindlager, während die Verlassenen ihre Grenzen am Bollwerk verteidigen. Die Vermittlung und Führung des Kampfes gegen die untoten Kessel obliegt der neutralen Argentumdämmerung, die Streiter beider Fraktionen unterstützt und Uthers Grabmal bewacht – den letzten wahrhaft geweihten Boden in der Region."}},faq={{q="Warum traf die Seuche dieses Gebiet so hart?",a="Andorhal war der landwirtschaftliche Umschlagplatz des nördlichen Lordaeron. Kel'Thuzad zielte vorsätzlich auf die regionale Versorgung ab, infizierte Getreidesilos und stellte gewaltige Pestkessel auf vier großen Gehöften auf, um den Untod rasch über Nahrungsmittellieferungen im gesamten Königreich zu verbreiten.",al={"warum westliche pestländer verseucht","was geschah mit andorhal","warum kessel hier"}},{q="Wer kontrolliert Herdweiler im Norden?",a="Herdweiler und seine Festung, Burg Mardenholde, werden vom Scharlachroten Kreuzzug beherrscht. Obwohl es ursprünglich ein regionales Verwaltungszentrum Lordaerons war, richten die Fanatiker nun jeden Außenstehenden hin, der sich ihren Grenzen nähert, und begegnen allen Nicht-Kreuzfahrern mit Misstrauen.",al={"herdweiler fraktion","wer lebt in burg mardenholde","ist herdweiler freundlich"}},{q="Wo finden Spieler der Allianz und der Horde sichere Außenposten?",a="Die Allianz unterhält das Zugwindlager nahe der südlichen Grenze zum Alteracgebirge, das einen Flugmeister und Verbündete der Argentumdämmerung bietet. Die Horde operiert vom Bollwerk an der Westgrenze aus, wenn man aus Tirisfal anreist.",al={"wo sind die flugpunkte","horde lager wpl","allianz lager wpl"}},{q="Welchen Zweck haben die Pestkessel auf den Feldern?",a="Vom Kult der Verdammten auf dem Teufelssteinfeld, Dalsons Tränenfeld, Dem trostlosen Feld und Gahrrons Trauerfeld errichtet, pumpen diese Kessel unentwegt Seuchendämpfe in Luft und Boden. Agenten der Argentumdämmerung rekrutieren Abenteurer, um die Kessellords zu erschlagen und Gegenmittel für die giftigen Gebräue zu entwickeln.",al={"was sind die kessel","kessel zweck","teufelsstein kessel"}},{q="Was ist Scholomance und wo befindet es sich?",a="Scholomance ist eine unterirdische Akademie der Nekromantie, die von der Geißel und dem Kult der Verdammten betrieben wird. Sie liegt verborgen unter den Ruinen von Darrowehr, einer Inselfestung im südöstlichen Gewässer des Darrowmeresees.",al={"scholomance standort","wo ist scholomance","darrowehr dungeon"}},{q="Ist irgendein Teil der Westlichen Pestländer unverderbt?",a="Uthers Grabmal, das auf Trauerhügel nahe dem Südrand der Zone liegt, bleibt vollkommen heilig und von der Seuche unberührt. Es steht als geweihter Gedenkort für den gefallenen Obersten General Uther den Lichtbringer und den verlorenen Orden der Silbernen Hand.",al={"heiliger boden in wpl","ist uthers grabmal rein","uthers grabmal sicher"}}},fp="19,342,28.378.0,18.438.0,16.443.0,41.268.0,37.227.0,56.233.0,58.277.0,44.206.0,51.204.0"}
P.entries["zone:westfall"] = {n="Westfall",s="Die Höfe in Westfall liegen schutzlos da, und die Bruderschaft der Defias beherrscht weite Teile des Umlands. Einst die Kornkammer von Sturmwind, kommt das Gebiet nun ohne Unterstützung der Krone oder militärische Garnisonen kaum zurecht.",h="Die Höfe in Westfall liegen schutzlos da, und die Bruderschaft der Defias beherrscht weite Teile des Umlands.",kw={"die todesminen","defias","erntegolem","miliz","mondbruch","saldean","späherkuppe","starkmantel","vancleef","westfall"},ang={["class:Rogue"]="Als Schurke findest Du in ganz Westfall einen Schattenkrieg vor, in dem Spione von SI:7 auf die abgebrühten Kundschafter, Diebe und Meuchelmörder der Bruderschaft der Defias treffen.",["faction:Alliance"]="Als Reisender der Allianz kannst Du sehen, wie die Volksmiliz die Späherkuppe hält. Ohne sie würde die Bruderschaft der Defias die südlichen Zugänge zum Wald von Elwynn kontrollieren.",["profession:Cooking"]="Als Koch kannst Du erfahren, wie die geplagten Siedler auf Saldeans Farm mit zähen einheimischen Tieren auskommen und Reisenden beibringen, Westfall Stew zuzubereiten.",["race:Human"]="Als Mensch zeigt Westfall den politischen Verfall von Sturmwind. Die Bauern, die im Dreck hungern, wurden von den Adligen im Stich gelassen, für die sie sich abmühten, Nahrung anzubauen."},sec={{t="Ein vergessenes Land",b="Westfall versorgte das Königreich Sturmwind einst mit seinen Weiden und Weizenfeldern. Nach dem Zweiten Krieg wurden die Finanzen des Königreichs knapp, und seine Anführer vernachlässigten das Gebiet. Sturmwind schickte seine Ressourcen anderswohin und zog seine Garnisonen ab, sodass das Land brachlag. Heute machen ödes Weideland, scharfe Küstenwinde, abtrünnige Erntegolems und Gnolle des Flusspfotenstamms den wenigen Siedlern, die noch geblieben sind, das Überleben schwer."},{t="Der Aufstieg der Bruderschaft",b="Die Ankunft der Bruderschaft der Defias beschleunigte Westfalls Niedergang. Die Banditen tragen rote Masken und folgen einem Anführer, dessen Namen niemand im Umland kennt. Sie machten Westfall zu ihrer Hochburg, verbrannten die Felder der Bauern, versalzten den Boden und bemächtigten sich verlassener Minen. Von Mondbruch aus, einer Geisterstadt, beherrscht die Bruderschaft fast das gesamte Umland, auch wenn sie es dem Namen nach nicht tut."},{t="Die Volksmiliz",b="Das Haus der Edlen hat Westfalls Notlage ignoriert, also haben die Einheimischen selbst zu den Waffen gegriffen. Auf der Späherkuppe stellte Gryan Starkmantel die Volksmiliz auf, eine Freiwilligentruppe, die Gnollen und Banditen die Stirn bietet. Sturmwind schickt weder reguläre Soldaten noch Vorräte. Die Miliz ist auf umherziehende Abenteurer angewiesen, die die Defias zurückdrängen und die verbliebenen Höfe schützen."},{t="Steinmetze mit roten Masken",b="Edwin van Cleef führt die Bruderschaft an. Er war der Gildenmeister, der Sturmwind wiederaufbaute, doch das Haus der Edlen verweigerte seinen Steinmetzen den Lohn, und Aufstände trieben sie fort. In Westfall griffen sie zur roten Maske. Die Banditen, die seine Felder niederbrennen, sind dieselben Hände, die die Mauern der Hauptstadt errichteten."},{t="Die Verschwörung in den Todesminen",b="Unter Mondbruch hat Edwin van Cleef in den verlassenen Goldstollen der Todesminen Halsabschneider, Goblins und Abtrünnige versammelt. Die Bruderschaft baut dort einen gewaltigen gepanzerten Koloss, der die Küste hinaufsegeln und Sturmwind bombardieren soll."}},faq={{q="Warum sind so viele Höfe in Westfall verlassen?",a="Sturmwind zog seine Garnisonen ab, als ihr Unterhalt zu teuer wurde, und ließ Westfall ungeschützt zurück. Daraufhin nahm die Bruderschaft der Defias weite Teile des Umlands ein, vertrieb die Siedler, verbrannte Ackerland und programmierte mechanische Erntewächter zu tödlichen Wachposten um.",al={"verlassene höfe","warum ist westfall tot","warum liegt das land brach"}},{q="Warum schickt Sturmwind keine Truppen, um Westfall zu helfen?",a="Die Schatzkammer des Königreichs ist überlastet, und das Haus der Edlen räumt Bedrohungen in anderen Ländern höhere Priorität ein. Auch Intrigen am Hof haben Westfall heimlich um Aufmerksamkeit und Vorräte gebracht, sodass die Bewohner sich selbst verteidigen müssen.",al={"warum schickt sturmwind keine armee","wo sind die wachen","hilfe aus sturmwind"}},{q="Was ist die Volksmiliz?",a="Gryan Starkmantel stellte auf der Späherkuppe die Volksmiliz auf, um Westfall zu verteidigen. Da die Krone keine Soldaten schickt, schlossen sich Bauern und Siedler zusammen, um gegen die Bruderschaft der Defias und die Gnolle des Flusspfotenstamms zu kämpfen.",al={"volksmiliz","miliz auf der späherkuppe","armee von gryan starkmantel"}},{q="Wer führt die Bruderschaft der Defias in Westfall an?",a="Edwin van Cleef, ehemaliger Gildenmeister der Steinmetzgilde, führt die Bruderschaft der Defias an. Er beaufsichtigte den Wiederaufbau von Sturmwind, führte dann seine Arbeiter nach Westfall und bewaffnete sie, nachdem ein erbitterter Streit um die Bezahlung in Aufständen geendet hatte.",al={"anführer der defias","wer führt die defias an","vancleef"}},{q="Was verbirgt sich in Mondbruch?",a="Unter einer unscheinbaren Scheune in Mondbruch liegt der Eingang zu den Todesminen. Die Bruderschaft der Defias machte aus der verlassenen Goldmine eine unterirdische Festung und Werft für ihren Krieg gegen Sturmwind.",al={"geheimnis von mondbruch","was ist in den todesminen","mine von mondbruch"}},{q="Warum greifen die mechanischen Vogelscheuchen Menschen an?",a="Goblinbastler, die mit den Defias verbündet sind, erbeuteten die mechanischen Erntewächter, die ursprünglich für die Feldpflege und zur Vertreibung von Schädlingen gebaut wurden. Sie rüsteten sie um, damit sie Felder patrouillieren und Eindringlinge töten.",al={"angreifende erntegolems","erntewächter","böse vogelscheuchen"}}},fx={cd1e134e={q="Was ist Westfall?",a="Westfall ist das windgepeitschte westliche Territorium des Königreichs Sturmwind, das westlich des Wald von Elwynn und südlich bis zum Meer liegt. Einst die fruchtbare Kornkammer des Königreichs, ernährten seine sanften Hügel und weiten Weiden Sturmwind über Generationen hinweg. Heute, von der Krone vernachlässigt und von Konflikten verwüstet, ist es zu brachliegenden Staubebenen, verfallenen Gehöften und einem Gesetzlosen-Gebiet verkommen.",al={"was ist diese zone","erzähl mir von westfall","westfall lore"}},["44cadea7"]={q="Warum ist es hier so leer?",a="Eine Kombination aus Dürre, Vernachlässigung und Räubertum hat die Landschaft entvölkert. Nach dem Zweiten Krieg konzentrierte Sturmwind seine Soldaten anderswo und ließ die örtlichen Gehöfte schutzlos zurück. Als sich die Bruderschaft der Defias erhob, vertrieben sie Bauern, brannten Ackerland nieder und versalzten die Felder. Ohne königliche Garnisonen, die sie schützen konnten, flohen die meisten Bewohner oder verhungerten.",al={"warum ist westfall unfruchtbar","warum so leer","warum sind hier keine leute"}},["1a97e791"]={q="War Westfall schon immer so arm?",a="Ganz und gar nicht. Über Generationen hinweg war Westfall Sturmwinds stolzes landwirtschaftliches Herzland, berühmt für goldene Weizenfelder, reichen Boden und ertragreiche Goldminen wie Jangolode und die Todesminen. Seine Nahrung ernährte die Hauptstadt, und seine Minen füllten die königlichen Schatzkammern, bevor Kriege und innere Unruhen es unfruchtbar machten.",al={"war westfall schon immer arm","war westfall früher wohlhabend","westfall vergangenheit"}},["1d4a9481"]={q="Wer ist die Bruderschaft der Defias?",a="Die Bruderschaft der Defias ist eine riesige kriminelle Organisation, die sich aus abtrünnigen Steinmetzen, Dieben, Wegelagerern und Ausgestoßenen zusammensetzt. Unter der Führung von Edwin van Cleef besetzten sie die verlassenen Ackerflächen und Minen von Westfall, um einen erbitterten Schattenkrieg gegen das Königreich Sturmwind zu führen, mit der Absicht, Vergeltung für unbezahlte Schulden und vermeintliche Verrate zu üben.",al={"wer sind die defias","was ist die bruderschaft der defias","wer sind diese banditen"}},b6953315={q="Warum tragen die Defias rote Bandanas?",a="Rote Bandanas sind das Markenzeichen der Bruderschaft der Defias, und das Material zeigt den Rang eines Mitglieds an. Red Silk Bandanas kennzeichnen hochrangigere Mitglieder; Späherin Riell bittet Abenteurer, sie als Beweis für deren Tod zu sammeln.",al={"warum rote bandanas","defias rote masken","bedeutung rote masken"}},["908b4fe1"]={q="Was wollen die Defias in Westfall?",a="Sie behandeln Westfall als ihre souveräne Festung und ihren Stützpunkt. Indem sie die Goldminen kontrollieren, Nahrungsmittelvorräte beschlagnahmen und loyale Bauern vertreiben, können sie im Geheimen ihre Streitkräfte und Maschinen abseits von Sturmwinds direktem Blickfeld aufbauen, während sie den Untergang des Königreichs planen.",al={"was wollen die defias","defias ziele westfall","warum sind die defias in westfall"}},d384bc2d={q="Warum wurde ich nach Westfall geschickt?",a="Ihr wurdet hierher geschickt, weil Sturmwinds reguläres Militär sich weigert oder nicht in der Lage ist, Truppen nach Westfall zu entsenden, was das Territorium an den Rand des Zusammenbruchs durch das Räubertum bringt. Die Behörden im Wald von Elwynn leiten fähige Abenteurer nach Westen, um die kämpfenden Einheimischen zu unterstützen, die verzweifelt nach Hilfe suchen.",al={"warum bin ich in westfall","wer hat mich nach westfall geschickt","warum wurde ich hierher geschickt"}},d59f010f={q="Wer ist Gryan Starkmantel?",a="Gryan Starkmantel ist ein Paladin der Silbernen Hand und stammt aus Westfall. Als er nach dem Kampf in Lordaeron während des Dritter Krieg nach Hause zurückkehrte, fand er seine Heimat von Banditen überrannt und vom Militär Sturmwinds verlassen vor. Als Reaktion darauf versammelte er lokale Verteidiger, um die Bürgerwehr bei Späherkuppe zu gründen.",al={"wer ist starkmantel","gryan starkmantel","wer führt späherkuppe"}},af1c3ddb={q="Hat Gryan Starkmantel tatsächlich das Sagen in Westfall?",a="Praktisch gesehen, ja. Während der junge König in Sturmwind rechtlichen Anspruch auf Westfall erhebt, übt die Krone hier so gut wie keine wirkliche Autorität aus. Starkmantel und seine freiwillige Bürgerwehr bei Späherkuppe stellen die einzige funktionierende Verteidigung und Strafverfolgung dar, die im Reich verblieben ist.",al={"wer regiert westfall","ist starkmantel der anführer","wer hat das sagen"}},ec2fd06e={q="Hat Sturmwind sich wirklich geweigert, die Steinmetze zu bezahlen?",a="Ja. Das Haus der Adligen hatte durch die Ausweitung militärischer Expeditionen an anderen Orten erschütternde Schulden angehäuft, was das Königreich fast in den Bankrott trieb. Beeinflusst von Hofintrigen und aristokratischer Arroganz boten die Adligen für die gewaltige Arbeit nur ein Almosen an und weigerten sich schlichtweg, die vollständigen Verträge einzuhalten.",al={"hat sturmwind die steinmetze betrogen","warum haben die adligen nicht bezahlt","bezahlungsstreit der steinmetze"}},cf60f690={q="Warum gibt es so viele Gnolle in Westfall?",a="Die Gnolle des Flusspfotenrudels sind über die Grenze migriert, um das Fehlen von Soldaten aus Sturmwind auszunutzen. Schlimmer noch, die Bruderschaft der Defias heuerte sie aktiv als Söldner an und stationierte sie in den Hügeln und Ebenen, um Reisende zu überfallen und alle überlebenden Gehöfte zu schikanieren.",al={"warum sind hier gnolle","flusspfoten gnolle westfall","danuvin gnolle"}},e40fa3bd={q="Was ist Mondbruch?",a="Mondbruch war einst der primäre Markt und die Bergbaustadt im südlichen Westfall. Über dem alten Eingang zu den Todesminen gelegen, wurde es vollständig von der Bruderschaft der Defias besetzt und geräumt, die nun die leeren Gebäude als perimetrischen Schutz für ihre unterirdische Festung nutzen.",al={"was ist mondbruch","mondbruch lore","erzähl mir von mondbruch"}},["46f1c864"]={q="Wohin führt die Untersuchung der Defias?",a="Eure Ermittlungen decken das geheime Herz der Bruderschaft unter Mondbruch in den Todesminen auf. Dort, tief in den unterirdischen Höhlen, überwacht Edwin van Cleef den Bau eines gewaltigen, eisenbeschlagenen Juggernauts, der Sturmwind vom Meer aus beschießen soll, was zu einem direkten Angriff auf den Gildenmeister selbst führt.",al={"wohin führt die defias-questreihe","wie endet die defias-geschichte","abschluss todesminen"}},["27471424"]={q="Wie bin ich in Westfall gelandet?",a="Ihr seid wahrscheinlich über die Flussbrücke aus dem Wald von Elwynn der Straße nach Westen gefolgt, geschickt von Behörden oder Freunden von Späherkuppe. Da Sturmwind überlastet ist und keine königlichen Truppen entbehren kann, hat sich in den benachbarten Ländern herumgesprochen, dass Gryan Starkmantel und die lokalen Bauern verzweifelt fähige Hände benötigen. Ob Ihr dem Ruf nach Hilfe gefolgt seid oder einfach nur dem Königsweg auf der Suche nach Arbeit gefolgt seid, Ihr seid in ein Reich eingetreten, das die Soldaten des Königreichs so gut wie aufgegeben haben.",al={"wie bin ich hierher gekommen","wie bin ich nach westfall gekommen","wie bin ich hier gelandet"}},["6324593c"]={q="Was soll ich in Westfall tun?",a="Eure Hauptmission ist es, die Bürgerwehr bei Späherkuppe dabei zu unterstützen, die unzähligen Bedrohungen zurückzuschlagen, die die Provinz ersticken. Gryan Starkmantel braucht Freiwillige, um die aggressive Tierwelt auszudünnen, die abtrünnigen Erntebeobachter zum Schweigen zu bringen, die durch brachliegende Felder streifen, und die Gnolle des Flusspfotenrudels zurückzudrängen. Vor allem seid Ihr damit beauftragt, die schwer fassbare Bruderschaft der Defias zu jagen, aufzudecken, wo sie sich verstecken, und ihren Würgegriff auf das zu lösen, was von Westfalls kämpfenden Gehöften übrig geblieben ist.",al={"was sollte ich hier tun","was mache ich in westfall","warum bin ich hier"}},c01912f7={q="Was geschah mit der Stonemasons Guild?",a="Unter Gildenmeister Edwin van Cleef verbrachte die Stonemasons Guild nach dem Ersten Krieg Jahre damit, Sturmwind wiederaufzubauen. Als die Arbeit getan war, weigerte sich das House of Nobles, die vereinbarte Summe zu zahlen. Nachdem friedliche Bitten gescheitert waren, wurde die Gilde gewaltsam aufgelöst, was wütende Aufstände entfachte, die die Steinmetze ins Exil trieben.",al={"was geschah mit den steinmetzen","geschichte der steinmetzgilde","wer waren die steinmetze"}}},fp="8,190,18.391.0,27.355.0,20.380.0,19.294.1,24.254.1,44.264.0,52.230.0,29.199.0,45.227.1,32.204.1,51.187.0"}
P.entries["zone:wetlands"] = {n="Sumpfland",s="Das Sumpfland ist ein weitläufiger, nebelverhangener Sumpf, eingebettet zwischen den Bergen von Khaz Modan und den Ufern der Baradinbucht. Historisch gebeutelt von Kriegen der Zwerge und Invasionen der Orcs, dient es als zerklüftete Pufferzone zwischen Eisenschmiede und den nördlichen Ländern von Lordaeron. Der befestigte Hafen von Menethil bildet die wichtigste Lebensader der Allianz in einer durchnässten Wildnis, die von Orcs des Drachenmals, Murlocs und Gnollen überrannt wird.",h="Das Sumpfland ist ein weitläufiger, nebelverhangener Sumpf, eingebettet zwischen den Bergen von Khaz Modan...",kw={"baradinbucht","drachenmal","dun algaz","dun modr","grim batol","menethil","hafen von menethil","thandol-übergang","sumpfland"},ang={["faction:Alliance"]="Der Hafen von Menethil dient der Allianz als wichtigstes Tiefseetor über das Große Meer und verbindet die Königreiche des Ostens mit den Expeditionsaußenposten in Kalimdor.",["profession:Mining"]="Die Hügel und höhlenartigen Tiefen des Thelgenfelsens bergen reiche Mineraladern, darunter seltene Vorkommen von Pyrophorerz, das von Zwergenbergleuten und Ingenieuren geschätzt wird.",["race:Dwarf"]="Für Zwerge ist das Sumpfland ein bittersüßer Ort, geprägt vom Verlust von Dun Modr, der uralten Tragödie von Grim Batol und den anhaltenden Mühen, König Magnis Handelsroute in den Norden zu verteidigen."},sec={{t="Ein Land aus Wasser und Ruinen",b="Unter dem hoch aufragenden Abgrund des Steinwerkdamms erstreckt sich das Sumpfland als kalte, wasserdurchtränkte Weite, die in ewigen Nebel und einheitlich grauen Himmel gehüllt ist. Einst Heimat blühender Zwergensiedlungen, sind die Marschen heute übersät von versunkenen Steinruinen, nassen Mooren und tückischen Sümpfen. Abenteurer, die die Region betreten, müssen sich durch schmale Pässe schlagen – entweder von Loch Modan aus durch den verbarrikadierten Engpass von Dun Algaz nach Norden oder über die hoch aufragenden Bögen des Thandol-Übergangs aus dem Arathihochland."},{t="Die Narben von Grim Batol",b="Die östlichen Gefilde des Sumpfes werden von der unheilvollen Präsenz von Grim Batol beherrscht, der einstigen Festung der Wildhämmer. Nach ihrer Entweihung während des Krieges der drei Hämmer wurde sie während des Zweiten Krieges zur befestigten Bastion des Drachenmalklans. Als sich der rote Drachenschwarm aus der Gefangenschaft der Orcs befreite, zerschmetterte seine feurige Rache die orcischen Streitkräfte und verwüstete die umliegenden Hänge. Heute bewachen rote Wyrmkin die Tore des Drachenmals vor allen Eindringlingen, während verwilderte Überreste des Drachenmalklans in verstreuten Lagern in den Hügeln hausen und weiterhin Reisende im gesamten Sumpf überfallen."},{t="Hafen der Westküste",b="An den Gestaden der Baradinbucht gelegen, ist der Hafen von Menethil das pulsierende Herz des Handels und der Logistik der Allianz in Khaz Modan. Zu Ehren von König Terenas Menethil II. benannt, verbindet dieser wehrhafte Hafen die Östlichen Königreiche mit dem fernen Kalimdor durch regelmäßige Transportschiffe, die zur Insel Theramore und über Süderstade nach Auberdine fahren. Trotz seiner strategischen militärischen Bedeutung und der soliden Zwergenarchitektur ist der Hafen ständig durch Küstenmurlocs, Sumpfkreaturen und Küstenräuber bedroht, die Schiffen auflauern, welche die felsigen Kanäle befahren."},{t="Belagerte Grenzgebiete",b="Das Sumpfland ist an mehreren Fronten ein aktives Kriegsgebiet. Weit im Norden haben Dunkeleisenzwerge unter dem Hexenmeister Balgaras the Foul den Thandol-Übergang durch Bomben sabotiert und die Stadt Dun Modr überrannt, wodurch Überland-Nachschubzüge abgeschnitten wurden. Unterdessen treiben Mosshide-Gnolle in den zentralen Mooren ihr Unwesen und bedrohen selbst uralte Beschützer wie Rethiel den Sumpfhüter. Zwischen abtrünnigen Kriegstrupps der Orcs, Infiltratoren der Dunkeleisenzwerge und verfluchten Schiffswracks entlang der Küste erfordert das Halten des Sumpfes ständige Wachsamkeit."}},faq={{q="Wie reise ich zu Fuß ins Sumpfland?",a="Abenteurer der Allianz reisen im Allgemeinen von Loch Modan aus nach Norden durch den Gebirgspass von Dun Algaz. Reisende der Horde, die aus dem Norden kommen, können vom Arathihochland aus den Thandol-Übergang überqueren. Passt auf, denn beide Passagen sind von feindlichen Kräften wie Orcs des Drachenmals und Dunkeleisenzwergen umkämpft.",al={"wie man ins sumpfland gelangt","weg ins sumpfland","lauf ins sumpfland"}},{q="Wohin fahren die Schiffe im Hafen von Menethil?",a="An den Docks im Hafen von Menethil werden zwei bedeutende Fährverbindungen nach Kalimdor betrieben: Ein Schiff legt in Süderstade im Vorgebirge des Hügellands an und fährt dann über das Große Meer nach Auberdine an den Gestaden der Dunkelküste, während das andere nach Süden zur Insel Theramore in den Düstermarschen segelt.",al={"schiffe von menethil","schiffe im hafen von menethil","wohin fährt das schiff im sumpfland"}},{q="Was ist Grim Batol und warum wird es bewacht?",a="Grim Batol ist eine uralte Zwergenfestung, die nach dem Krieg der drei Hämmer verlassen und später vom Drachenmalklan besetzt wurde. Nach dem Zweiten Krieg vertrieb der befreite rote Drachenschwarm die Orcs und versiegelte den Berg. Mächtige rote Drachenbrut und Wyrmkin patrouillieren an den Toren des Drachenmals, um zu verhindern, dass irgendjemand die verfluchten Hallen betritt.",al={"warum gibt es drachen bei grim batol","grim batol rote drachen","tore des drachenmals"}},{q="Was geschah mit Dun Modr?",a="Dun Modr war eine nördliche Zwergenfestung, die den Thandol-Übergang bewachte. Vor Kurzem wurde sie von Dunkeleisenzwergen unter der Führung von Balgaras the Foul angegriffen und überrannt. Die Überlebenden unter der Führung von Rhag Garmason halten in der Nähe ein umkämpftes Lager, während sie darum kämpfen, ihre Stadt zurückzuerobern.",al={"wer hat dun modr zerstört","ruinen von dun modr","dunkeleisenzwerge in dun modr"}},{q="Wer ist Rethiel der Sumpfhüter?",a="Rethiel ist eine uralte Sumpfbestie, die im Grünen Gürtel des Sumpflands weilt. Er bittet Reisende um Hilfe, um die Flut der aggressiven Mosshide-Gnolle einzudämmen und erkrankte Fen Creepers zu erlegen, damit sich die Marschen erholen können.",al={"der grüne gürtel","rethiel sumpfland","wer ist der sumpfhüter"}},{q="Woher kamen all die Orcs im Sumpf?",a="Die Orcs gehören dem Drachenmalklan an, der sich ursprünglich während des Zweiten Krieges in Grim Batol verschanzt hatte. Nachdem sie vom befreiten roten Drachenschwarm vernichtend geschlagen worden waren, flohen die überlebenden Orcs hinab in den Sumpf und die Hügel, wo sie immer noch Überfälle auf Straßen und Reisende verüben.",al={"warum gibt es orcs im sumpfland","sumpfland drachenmal","drachenmalklan sumpfland"}}},fx={["4984d286"]={q="Warum ist es hier überall Sumpf?",a="Das Sumpfland liegt in einem tiefen Becken, das an drei Seiten von hoch aufragenden Gebirgszügen begrenzt wird, die den Abfluss aus den Höhen darüber auffangen. Es wird von zahllosen Flüssen, Teichen und Bächen gespeist, die in Richtung der Baradinbucht fließen und die Erde ständig feucht und kalt halten.",al={"warum ist das sumpfland ein sumpf","geografie des sumpflands","warum so viel wasser im sumpfland"}},["60c5b961"]={q="Wer lebt im Sumpfland?",a="Die wichtigste zivilisierte Präsenz ist die Allianz im Hafen von Menethil, zusammen mit zwergischen Bergsteigern, die darum kämpfen, wichtige Außenposten zu halten. Die Wildnis wird jedoch von feindlichen Kräften dominiert: abtrünnige Orcs des Drachenmals, die sich in den östlichen Ausläufern verstecken, Mosshide-Gnolle, die durch die Moore streifen, Murlocs, die an den Küsten kriechen, und gewalttätige Dunkeleisenzwerge, die von Dun Modr aus nach Süden drängen.",al={"wer lebt hier","fraktionen im sumpfland","bewohner des sumpflands"}},["8d21dccb"]={q="Was ist der Hafen von Menethil und wer betreibt ihn?",a="Der Hafen von Menethil ist eine schwer befestigte Hafenstadt auf einer Insel in der Baradinbucht und dient als wichtigstes Küstentor der Allianz in Khaz Modan. Benannt zu Ehren von König Terenas Menethil II. von Lordaeron, wird sie von Zwergen und verbündeten Menschen unterhalten, durch die dicken Steinmauern von Burg Menethil geschützt und von der Garnison von Hauptmann Starkfaust bewacht.",al={"hafen von menethil","wer verwaltet menethil","stadt menethil"}},fd9bb568={q="Warum haben die Zwerge hier einen Hafen gebaut?",a="Während des Zweiten Krieges errichtete Orgrim Schicksalshammer hier eine Werft, um die Horde über die Baradinbucht nach Lordaeron zu übersetzen. Nachdem die Allianz die Orcs vertrieben hatte, beanspruchte sie den Ort für sich und baute ihn zu einem blühenden Hafen aus, wodurch wichtige maritime Versorgungsrouten etabliert wurden, die Khaz Modan sowohl mit menschlichen Verbündeten als auch mit fernen Ländern jenseits des Meeres verbinden.",al={"warum hafen von menethil","warum einen hafen im sumpf bauen","grund für den hafen von menethil"}},["4cff40a7"]={q="Ist der Hafen von Menethil Gebiet der Allianz?",a="Ja. Der Hafen von Menethil ist eine offizielle Festung der Allianz. Obwohl es eine raue, geschäftige Hafenstadt voller Seeleute, Händler, Reisender und grober Hafenarbeiter ist, weht dort das Banner der Allianz und sie wird von den Streitkräften aus Eisenschmiede verteidigt.",al={"ist menethil allianz","fraktion hafen von menethil","wem gehört der hafen von menethil"}},["6dc9c02b"]={q="Wer hat hier das Sagen?",a="Es gibt keinen einzelnen Herrscher über das ungezähmte Marschland. Die Autorität der Allianz konzentriert sich auf den Hafen von Menethil unter Hauptmann Starkfaust und der Garnison innerhalb von Burg Menethil. Außerhalb der Hafenmauern ist der Sumpf ein gesetzloses Grenzland, um das sich Militärpatrouillen, orcische Kriegsherren und urtümliche Bestien streiten.",al={"wer führt das sumpfland","kommandant des sumpflands","wer ist hier der chef"}},b8a9f96f={q="Wer ist Hauptmann Starkfaust?",a="Hauptmann Starkfaust ist der zwergische Kommandant, der die Garnison im Hafen von Menethil befehligt. Von der Sicherheit des Hafens aus koordiniert er Verteidigungsoperationen im gesamten Sumpf und beauftragt fähige Abenteurer damit, die unaufhörlichen Überfälle der nahegelegenen Orcs des Drachenmals einzudämmen.",al={"hauptmann starkfaust sumpfland","starkfaust lore","wer ist starkfaust"}},["38351a9f"]={q="Wer sind die Orcs des Drachenmals und warum sind sie hier?",a="Der Drachenmalclan ist ein brutaler Orcclan, der die Dämonenseele benutzte, um Alexstrasza und den roten Drachenschwarm während des Zweiten Krieges zu versklaven, und der von den Höhen von Grim Batol aus herrschte. Als die Drachenkönigin befreit wurde, zerschlugen die rachsüchtigen Drachen den Clan und zerstreuten die Überlebenden in die Sümpfe und Berge des Sumpflands, wo sie weiterhin eine gewalttätige, anhaltende Bedrohung darstellen.",al={"drachenmal sumpfland","warum sind drachenmal im sumpfland","orcs des drachenmals"}},ecc875bb={q="Wer sind die Dunkeleisenzwerge und warum greifen sie Dun Modr an?",a="Die Dunkeleisen sind ein tückischer, schattenwirkender Zwergenclan, der lange aus Eisenschmiede verbannt war. Sie nutzten aus, dass die Streitkräfte der Allianz im Ausland eingesetzt waren, stießen nach Norden vor, besetzten die Stadt Dun Modr und sabotierten den Thandol-Übergang, um wichtige Kommunikationswege zu kappen und Gebiete in Khaz Modan zurückzuerobern.",al={"dunkeleisen dun modr","warum dunkeleisen im sumpfland","dunkeleisen angriff sumpfland"}},["0f0d7fa8"]={q="Was ist der Thandol-Übergang und warum ist er wichtig?",a="Der Thandol-Übergang ist ein prächtiges Paar massiver steinerner Zwergenbrücken, die die Schlucht zwischen dem nördlichen Khaz Modan und dem Arathihochland überspannen. Er wurde nach dem Krieg der drei Hämmer gebaut, um Handel und Freundschaft mit den Wildhämmern zu erleichtern, und ist die einzige Landverbindung zwischen den südlichen Königreichen und dem nördlichen Lordaeron.",al={"thandol-übergang","thandol brücke","warum ist der thandol-übergang wichtig"}},faff9f74={q="Warum wollen die Dunkeleisen ihn in die Luft jagen?",a="Durch die Zerstörung des Thandol-Übergangs wollen die Dunkeleisen Eisenschmiede und Khaz Modan vollständig von den Verbündeten der Allianz in Lordaeron isolieren. Das Kappen dieser Überland-Lebensader verhindert, dass Verstärkung nach Süden marschiert, um Dun Modr zurückzuerobern oder bei weiteren Einfällen der Dunkeleisen zu helfen.",al={"warum thandol-übergang zerstören","dunkeleisen brückenkomplott","thandol-übergang in die luft jagen"}},eabba297={q="Wie bin ich im Sumpfland gelandet und wohin führt der Weg als Nächstes?",a="Die meisten Reisenden kommen an, indem sie von Loch Modan aus durch den Gebirgspass von Dun Algaz nach Norden marschieren oder die lange Reise mit dem Schiff in den Hafen von Menethil antreten. Von hier aus führt die Straße weiter nach Norden über den Thandol-Übergang in das Arathihochland, während Schiffe, die von den Docks ablegen, Abenteurer westlich über das große Meer tragen.",al={"wohin vom sumpfland aus","nächstes gebiet sumpfland","sumpfland weg"}},["75fb0ece"]={q="Ist das die Straße nach Eisenschmiede?",a="Ja. Wenn Ihr der Straße aus dem Sumpf nach Süden folgt, gelangt Ihr direkt in die engen Tunnel von Dun Algaz. Wenn Ihr das Gebirge durchquert, kommt Ihr nach Loch Modan, von wo aus die Hauptstraße nach Westen durch den Nordtorpass direkt in den Schnee von Dun Morogh und Eisenschmiede führt.",al={"straße nach eisenschmiede sumpfland","wie kommt man von sumpfland nach eisenschmiede","pfad nach eisenschmiede"}},["78aee5e0"]={q="Wie bin ich im Sumpfland gelandet?",a="Die meisten Reisenden der Allianz erreichen das Sumpfland, indem sie von Loch Modan aus nach Norden reisen und die engen Bergtunnel von Dun Algaz trotzen, um in die nebligen Marschlande unterhalb abzusteigen. Andere kommen mit dem Schiff von jenseits des großen Meeres an und segeln von den Küsten von Kalimdor in den Hafen von Menethil. Wer vom Arathihochland aus nach Süden reist, muss stattdessen die gefährlichen Übergänge des zerstörten Thandol-Übergangs meistern.",al={"wie bin ich hierher gekommen","wie kam ich im sumpfland an","woher bin ich gekommen"}},["87ca94d2"]={q="Was soll ich im Sumpfland tun?",a="Das Moor ist ein schwer bedrängtes Grenzland, in dem die Allianz an einem zerbrechlichen Stützpunkt festhält. Vom Hafen von Menethil aus seid Ihr dazu aufgerufen, wichtige Handelsrouten zu sichern und die verbliebenen Orcs des Drachenmals zurückzuschlagen, die das Tiefland überfallen. Weiter östlich und nördlich benötigen zwergische Bergsteiger Euren Stahl, um feindliche Gnollrudel einzudämmen, belagerten Ausgrabungsstätten zu helfen und Dunkeleisenzwerge zurückzudrängen, die drohen, den Thandol-Übergang vollständig zu unterbrechen.",al={"was soll ich hier tun","warum bin ich hier","was ist meine mission im sumpfland"}},["2cd88152"]={q="Was ist das Sumpfland?",a="Das Sumpfland ist ein kaltes, weitläufiges Marschland, eingebettet zwischen den Bergen von Khaz Modan und dem westlichen Meer. In ewigen grauen Nebel gehüllt, liegt es unmittelbar nördlich von Loch Modan und südlich vom Arathihochland. Einst Heimat zahlreicher Zwergensiedlungen, wurde die Region von vergangenen Kriegen verwüstet und dient nun als raue, ungezähmte Wildnis, die die Zwergenkönigreiche von den Ruinen von Lordaeron trennt.",al={"was ist das sumpfland","sumpfland lore","erzähl mir vom sumpfland"}}},fp="8,284,24.340.0,23.473.0,22.380.0,18.430.0,40.227.0,41.185.0,41.317.0,26.225.0,31.198.1,46.224.0"}
P.entries["zone:winterspring"] = {n="Winterquell",s="Winterquell ist ein riesiges, schneebedecktes Tal hoch an den nordöstlichen Hängen des Hyjal, direkt über den verzauberten Wäldern von Mondlichtung und dem Teufelswald. Die für ihre bittere Kälte, uralten Hochgeborenenruinen und umherstreifenden Spitzenprädatoren bekannte Region wird vom neutralen Goblin-Außenposten Ewige Warte zusammengehalten. Sie bleibt ein Land voller ungezähmter natürlicher Gefahren, das Überreste des blauen Drachenschwarms birgt und gleichzeitig an seinen südlichen Höhen gegen dämonische Verderbnis ankämpft.",h="Winterquell ist ein riesiges, schneebedecktes Tal hoch an den nordöstlichen Hängen des Hyjal, direkt über den...",kw={"blaue drachen","die flüsternde schlucht","donova schneeweh","ewige warte","frostsäbler","eiskappe","kel'theril","mazthoril","holzschlund","winterquell"},ang={["class:Druid"]="Hoch über Mondlichtung gelegen, besitzt Winterquell eine heilige Bedeutung als jener Ort, an dem Malfurion Sturmgrimm die Druiden der Kralle während des Dritten Krieges aus ihrem uralten Schlaf erweckte.",["faction:Alliance"]="Helden der Allianz besuchen regelmäßig Rivern Frostwind am Frostsäblerfelsen und arbeiten unermüdlich in der extremen Kälte, um sich die Treue der prestigeträchtigen Winterquell-Frostsäbler als Reittiere zu verdienen.",["profession:Herbalism"]="Winterquell ist der einzige bekannte Lebensraum für Eiskappen, ein unverzichtbares Gebirgskraut, das für fortgeschrittene alchemistische Rezepturen heiß begehrt ist, zusammen mit verstreutem Bergsilberweisling und seltenen Blüten von Schwarzem Lotus.",["profession:Mining"]="Die eisigen Felsen und Höhlenwände im gesamten Tal sind reich an wertvollen Mineralien und bergen häufig kleine sowie reiche Thoriumvorkommen nebst seltenen Echtsilberadern.",["race:NightElf"]="Winterquell ist eng mit der Geschichte der Elfen verknüpft: Hier befinden sich die Grabhügelbauten, in denen die Druiden der Kralle Jahrtausende lang ruhten, die tragischen Ruinen von Kel'Theril sowie freiliegende Wurzeln von Nordrassil, die während der Schlacht um den Hyjal beschädigt wurden."},sec={{t="Ein Reich des ewigen Frosts",b="Tausende Meter über der umliegenden Wildnis gelegen, ruht Winterquell unter klarer Bergluft und unerbittlichen Schneestürmen. Enorme, freiliegende Wurzeln des Weltenbaums Nordrassil durchziehen die Schneewehen wie hoch aufragende Holzbögen, verzerrt und verdreht während der Entscheidungsschlachten des Dritten Krieges. Während weite Teile des nördlichen Kalimdor von dichten Wäldern und warmem Klima geprägt sind, ist Winterquell ein stilles Land aus gemäßigten Gebirgswäldern, felsigen Klippen und gefrorenen Seen – Heimat beeindruckender Frostsäbler, Chimären, Yetis und dickfelliger Winterbären."},{t="Kreuzungen und Außenposten",b="Um dieses Hochplateau zu erreichen, müssen die uralten, in den Fels geschlagenen Gänge der Holzschlundfeste durchquert werden. Diese werden von unverdorbenen Furbolgs bewacht, die jeden Reisenden aus dem Teufelswald oder Mondlichtung genau mustern. Im Herzen des Tals liegt Ewige Warte, eine blühende Handelsstadt des Steamwheedle-Kartells. Die Goblins heißen sowohl Abenteurer der Allianz als auch der Horde mit offenen Kassenbüchern willkommen und bieten einen unverzichtbaren Zufluchtsort voller Ingenieurskunst, Handel und wärmender Feuer gegen den schneidenden Bergfrost."},{t="Alte Geister und blaue Drachen",b="Jahrhunderte bevor moderne Siedlungen entstanden, errichteten uralte Elfen die Stadt Kel'Theril am Seeufer. Nachdem leichtsinnige Zauberer der Hochgeborenen den verfluchten Kristall von Zin-Malor zerschlugen, verfielen sie dem Wahnsinn, sodass rastlose Phantome bis zum heutigen Tag zwischen den verfallenen Säulen und auf den gefrorenen Gewässern umherwandern. Weiter südlich erheben sich die höhlenartigen Höhen von Mazthoril, die traditionelle Festung des blauen Drachenschwarms auf Kalimdor. Hier wacht die Brut des Zauberwirkers Malygos unter der Führung der Schutzmatrone Haleh über arkane Strömungen und stellt sich lokalen Bedrohungen."},{t="Der drohende Schatten der Schlucht",b="Die Ruhe von Winterquell wird an seiner südlichsten Grenze in der Flüsternden Schlucht jäh gebrochen. Dort kriechen elitäre Dämonenstreitkräfte, verbliebene Legionen aus dem Dritten Krieg, durch zerklüftete Schluchten und versperren die hochgelegenen Zugänge zum Gipfel des Hyjal. Unterdessen sind die einheimischen Winterfall-Furbolgs finsterer Verderbnis anheimgefallen, was unabhängige Forscher wie Donova Schneeweh dazu veranlasst hat, dem um sich greifenden Makel nachzugehen, bevor die gesamte Tierwelt des Tals ihm zum Opfer fällt."}},faq={{q="Wie gelangt man nach Winterquell?",a="Reisende müssen durch die Holzschlundfeste ziehen, ein unterirdisches Tunnelnetz im nordöstlichen Teufelswald. Um die Höhlen friedlich zu durchqueren, muss man das Vertrauen der dort ansässigen Holzschlundfurbolgs gewinnen, die jeden als feindselig erachteten Eindringling angreifen. Hinter dem östlichen Ausgang erstrecken sich unmittelbar die schneebedeckten Hänge von Winterquell.",al={"nach winterquell gelangen","wie man nach winterquell kommt","eingang winterquell","holzschlundtunnel winterquell"}},{q="Wer kontrolliert die Stadt Ewige Warte?",a="Ewige Warte wird vom Steamwheedle-Kartell verwaltet, dem Handelsimperium der Goblins. Dank des strikten Profitstrebens und der Neutralität der Goblins haben sowohl Reisende der Horde als auch der Allianz Zugang zu Flugmeistern, Reparaturhändlern, Bankschließfächern und Handelswaren, sofern Besucher innerhalb der Stadtgrenzen den Frieden wahren.",al={"wer kontrolliert ewige warte","ewige warte fraktion","ist ewige warte neutral"}},{q="Was sind die Geister, die den Kel'Therilsee heimsuchen?",a="Es sind die Seelen der Hochgeborenen-Nachtelfen, die vor zehntausend Jahren die uralte Stadt Kel'Theril bewohnten. Als ihre Zauberer den gestohlenen Kristall von Zin-Malor manipulierten, löste dessen Zerstörung einen verheerenden Fluch aus. Nachfolgende Expeditionen von Hochelfen Jahrhunderte später verfielen gleichermaßen dem Wahnsinn und sind dazu verdammt, an der Seite ihrer Ahnen die gefrorenen Ruinen zu durchstreifen.",al={"kel'therilsee geister","die ruinen von kel'theril geister","wer ist bei kel'theril"}},{q="Warum sind die Winterfall-Furbolgs aggressiv?",a="Die Winterfall-Furbolgs sind einer sich ausbreitenden, unnatürlichen Verderbnis erlegen, die ihren Stamm in rasende Feindseligkeit gestürzt hat. Während die nahe gelegenen Holzschlundfurbolgs eisern an ihrem Verstand festhalten, sind die Winterfall finsteren Einflüssen verfallen. Forscher wie Donova Schneeweh versuchen daher, ihren Makel zu untersuchen und ihre Lager zu säubern.",al={"warum sind winterfall feindselig","winterfall stamm verderbnis","donova schneeweh furbolgs"}},{q="Was haust in Mazthoril?",a="Mazthoril ist der Hauptnistplatz und das Heiligtum des blauen Drachenschwarms auf Kalimdor. Tief in den höhlenartigen Türmen bewachen Drachkin, elitäre Welpen und uralte Drachen mächtige drakonische Relikte und arkane Geheimnisse unter dem wachsamen Auge von Haleh, der Gefährtin des Aspekts Malygos.",al={"mazthoril drachen","was ist mazthoril","blaue drachen in winterquell"}},{q="Was ist Die flüsternde Schlucht?",a="Die flüsternde Schlucht ist eine tückische Schlucht im südlichsten Teil des Tals, die von mächtigen Elitedämonen besetzt ist, welche aus dem Dritten Krieg übriggeblieben sind. Sie dient als schwer bewachter Vorposten entlang der gefährlichen Pfade, die zu den Höhen des Hyjal führen.",al={"die flüsternde schlucht dämonen","was ist in der flüsternden schlucht","hyjal tor winterquell"}},{q="Kann man hier Frostsäbler abrichten oder zähmen?",a="Am Frostsäblerfelsen im äußersten Norden des Tals kümmert sich der Nachtelf Rivern Frostwind um die einheimischen weißen Katzen. Abenteurer, die ihm bei der Beschaffung von Vorräten und dem Schutz des Rudels helfen, können sich als würdig erweisen, die Geheimnisse der Aufzucht und des Reitens eines Frostsäblers zu erlernen.",al={"frostsäbler reittier","rivern frostwind frostsäbler","wie man einen frostsäbler bekommt"}}},fp="12,328,26.408.0,23.361.0,26.385.0,31.374.0,29.250.0,30.220.0,45.324.0,43.293.0,28.244.0,26.191.0,39.225.0"}
P.entries["zone:zephras"] = {n="Insel Zephras",s="Die Insel Zephras ist eine fliegende Insel, die im Himmelswall schwebt, der Elementarebene der Luft. Sie dient den Skyborne als angestammte Heimat und Ausgangsort, deren Gesellschaft nun vor einer existenziellen Krise steht, da die Magie, die die Insel aufrechterhält, stetig schwindet. Da der Kontakt zu den benachbarten Himmelsreichen abgerissen ist, kämpfen ihre Bewohner gegen den elementaren Zusammenbruch und eintreffende Flüchtlinge.",h="Die Insel Zephras ist eine fliegende Insel, die im Himmelswall schwebt, der Elementarebene der Luft.",kw={"luftschiffe","anvilas","elementarebene","siroccas","skyborne","der himmelswall","valanaar","windsteine","zephras"},ang={["class:Shaman"]="Mitten in der Elementarebene der Luft gelegen, zeigt die Insel Zephras, was mit Elementarländern geschieht, wenn die Geister, die sie im Gleichgewicht halten, plötzlich verschwinden.",["race:Skyborne"]="Die Insel Zephras ist Eure angestammte Heimat und Euer Ausgangspunkt, doch ihre noch verweilende Schönheit täuscht über eine dringliche Krise aus einstürzendem Land und schwindender Elementarkraft hinweg."},sec={{t="Ein Reich in den Lüften",b="Die Insel Zephras ist eine isolierte Landmasse, die in den endlosen Winden des Himmelswalls treibt. Seit Generationen lebten die Skyborne hier Seite an Seite mit einheimischen Luftelementaren, die dabei halfen, die magischen Strömungen zu bewahren, die die Insel in der Luft hielten. Vor mehreren Jahrhunderten jedoch verschwanden diese elementaren Wächter spurlos. Beraubt ihrer Gegenwart und Obhut begannen die latenten Verzauberungen, die das Land trugen, langsam zu versagen, was dazu führte, dass Zephras allmählich aufbrach und instabil wurde."},{t="Abgeschnittene Horizonte",b="Zephras war nicht die einzige Zuflucht, die von den Skyborne innerhalb der Elementarebene bewohnt wurde. Auch die Schwesterninseln namens Anvilas und Siroccas trieben durch den Himmelswall, doch die Verbindung zwischen ihnen brach ab, nachdem die Elementare verschwunden waren. In jüngster Zeit ist es Flüchtlingen von diesen zerfallenden benachbarten Landmassen gelungen, auf der Suche nach Sicherheit Zephras zu erreichen, und sie brachten düstere Nachrichten mit: Die anderen Inseln lösen sich unter ihren Füßen vollends auf."},{t="Schwelle nach Azeroth",b="Da ihre eigene Landmasse langsam zerfällt, haben die Skyborne von Zephras begonnen, über die Grenzen des Himmelswalls hinaus nach Azeroth zu blicken. Von den Himmelsdocks von Valanaar brechen nun Luftschiffe auf, um seltene Rettungsanker in das Reich der Sterblichen zu schlagen. Diese Reisen verbinden das luftige Reich direkt mit Orten auf Azeroth, darunter den Ausläufern von Dalaran im Alteracgebirge und dem Himmelsschauerplateau in Mulgore."}},faq={{q="Wo befindet sich die Insel Zephras?",a="Die Insel Zephras liegt im Himmelswall, der Elementarebene der Luft, und nicht auf der Oberfläche von Azeroth. Sie schwebt inmitten der ewigen Wolken und Windströmungen dieser ätherischen Domäne.",al={"insel zephras ort","wo ist zephras","auf welcher ebene liegt zephras"}},{q="Warum bricht die Insel Zephras auseinander?",a="Die Insel war auf die Anwesenheit einheimischer Luftelementare angewiesen, die einst mit den Skyborne koexistierten. Vor mehreren Jahrhunderten verschwanden diese Elementare, wodurch die magischen Fundamente, die das fliegende Land verankern und erhalten, mit der Zeit langsam schwächer wurden und verfielen.",al={"warum stürzt zephras ein","insel zephras zerstörung","sterbende insel"}},{q="Was sind Anvilas und Siroccas?",a="Sie sind benachbarte schwebende Inseln im Himmelswall, die ebenfalls von den Skyborne bevölkert werden. Die Insel Zephras verlor die Verbindung zu beiden, als die Elementare verschwanden, und fliehende Flüchtlinge berichten nun, dass sowohl Anvilas als auch Siroccas im Nichts versinken.",al={"anvilas","siroccas","andere skyborne inseln"}},{q="Wie reist man zwischen der Insel Zephras und Azeroth?",a="Die Skyborne betreiben Himmelsdocks in der Siedlung Valanaar. Von diesen Docks aus starten Luftschiffe über die Grenzen der Ebenen hinweg nach Azeroth und landen nahe Dalaran im Alteracgebirge sowie am Himmelsschauerplateau in Mulgore.",al={"wie man zephras verlässt","zephras luftschiffe","reise nach azeroth"}},{q="Wer sind die Skyborne?",a="Die Skyborne sind die Bewohner, die auf der Insel Zephras und ihren Schwesternreichen am Himmel zu Hause sind. Nachdem sie Generationen lang im Himmelswall gelebt haben, stehen sie nun vor der langsamen Zerstörung ihrer fliegenden Heimat, da deren bindende Magie verblasst.",al={"skyborne volk","wer lebt auf zephras"}},{q="Wer lebt außer den Skyborne auf der Insel Zephras?",a="Abgesehen von friedlichen Dörfern und ankommenden Flüchtlingen wird die Insel von einheimischen Banditen, in Höhlen hausenden Nachtklauen und Bestien heimgesucht, die Gebiete wie den Kreischlingsbau und die Nachtklauenhöhle bewohnen.",al={"zephras bewohner","feinde auf zephras"}}},fx={["6e14d755"]={q="Werde ich die Insel irgendwann verlassen?",a="Ja. Während Insel Zephras als Euer Zuhause und anfänglicher Trainingsort dient, legen Luftschiffe von den Himmelsdocks in Valanaar ab, die durch dimensionale Risse das Festland von Azeroth erreichen und eine direkte Verbindung zu Dalaran im Alteracgebirge sowie zum Himmelsschauerplateau in Mulgore herstellen.",al={"werde ich zephras verlassen","insel zephras verlassen","können wir nach azeroth reisen"}},["19470e71"]={q="Wie bin ich auf Insel Zephras gelandet?",a="Ihr wurdet in das Volk der Himmelsgeborenen hineingeboren, den Shen'dorei, die auf dieser schwebenden Zuflucht hoch über Der Himmelswall, der Elementarebene der Luft, leben. Vor Jahrtausenden flohen Eure Vorfahren vor der Säuberung durch Prinz Tortheldrin in Eldre'Thalas und schlossen einen Pakt mit Windgeistern, die dieses Heiligtum in den Himmel hoben. Während andere Schwesterinseln wie Anvilas und Siroccas zerbröckeln oder in unerreichbare Ferne rücken, war Insel Zephras von Anfang an Euer Zuhause. Ihr beginnt Eure Reise hier inmitten Eures eigenen Volkes.",al={"wie bin ich hierher gekommen","wie habe ich insel zephras erreicht","warum bin ich hier aufgewacht","woher komme ich"}},["5dae6f41"]={q="Was soll ich auf Insel Zephras tun?",a="Euer Zuhause bröckelt unter Euren Füßen. Vor Jahrhunderten verschwanden die wohlwollenden Luftelementare und die arkanen Pylone, die Insel Zephras zusammenhalten, verlieren an Kraft. Flüchtlinge strömen von den zusammenbrechenden äußeren Inseln herbei, während rivalisierende Fraktionen, darunter Der Hohe Orden, die Windformer und die Al'Aketh, um das streiten, was noch übrig ist. Ihr müsst Eurem Volk helfen, interne Bedrohungen und wilde Bestien bezwingen, dabei helfen, die versagende Magie zu stabilisieren und letztendlich einen Weg hinunter nach Azeroth finden, bevor die Insel stürzt.",al={"was soll ich hier tun","was ist mein ziel hier","was mache ich auf insel zephras","warum bin ich hier"}},["1fd88046"]={q="Was ist die Insel Zephras?",a="Die Insel Zephras ist eine hoch aufragende, schwebende Landmasse innerhalb des Himmelswalls, der Elementarebene der Luft. Vor Jahrtausenden handelten verbannte Nachtelfen, die der Verfolgung in Eldre'Thalas entkamen, mit einheimischen Windgeistern, die die Insel in den Himmel hoben, um sie in Sicherheit zu bringen. Sie dient als angestammtes Heiligtum ihrer Nachkommen, den Himmelsgeborenen.",al={"was ist zephras","über die insel zephras","infos zur insel zephras"}},["7ea7c85c"]={q="Was ist auf der Insel Zephras passiert?",a="Die Insel Zephras wurde in den Himmelswall gehoben, nachdem hochgeborene Vorfahren sich von der blutigen Herrschaft von Prinz Tortheldrin in Eldre'Thalas abwandten. Die Himmelsgeborenen lebten jahrtausendelang in Harmonie mit Luftelementaren, doch vor Jahrhunderten verschwanden jene elementaren Gönner ohne Erklärung. Ohne ihre fortwährende Magie begannen die Pylone, die die Insel verankerten, zu verfallen, und Flüchtlinge von benachbarten, einstürzenden Inseln sind hierher geflohen, während interne Fraktionen um schwindende Ressourcen wetteifern.",al={"zephras geschichte","was ist hier auf zephras passiert","zephras lore"}},["70a3c6ae"]={q="Ist die Insel Zephras gefährlich?",a="Ja. Jenseits der drohenden physischen Gefahr, dass die Insel selbst instabil wird und vom Himmel stürzt, hat das Verschwinden der elementaren Beschützer das Land chaotisch hinterlassen. Banditenlager, feindliche Wildtierbaue und explosive politische Reibereien zwischen dem Hohen Orden, den Windformern und Al'Aketh machen Reisen außerhalb befestigter Siedlungen gefährlich.",al={"ist zephras gefährlich","zephras bedrohungen","gefahren auf zephras"}},b4875d06={q="Wo liegt die Insel im Vergleich zum Rest von Azeroth?",a="Die Insel Zephras ruht nicht auf der Oberfläche von Azeroth; sie treibt innerhalb des Himmelswalls, einer separaten dimensionalen Domäne, die von den Titanengeschmiedeten geschaffen wurde, um chaotische Luftelementare einzudämmen. Die einzigen physischen Verbindungen zwischen der Insel und der sterblichen Welt unterhalb sind spezialisierte Luftschiffe, die in Valanaar anlegen und über die Grenze zu Orten wie Dalaran und Mulgore reisen.",al={"wo liegt zephras zu azeroth","ist zephras in azeroth","zephras standort im vergleich zu azeroth"}},["2c89f95d"]={q="Wer sind die Al'Aketh?",a="Die Al'Aketh sind eine der rivalisierenden Fraktionen, die neben dem Hohen Orden und den Windformern um die Vorherrschaft auf der Insel Zephras kämpfen. Da die Pylone, die die Insel verankern, versagen und das Überleben immer verzweifelter wird, wetteifern die Al'Aketh aktiv um die Vorherrschaft und die Kontrolle über die verbleibenden mystischen Ressourcen der Insel.",al={"was sind die alaketh","fraktion al'aketh","wer ist alaketh"}}},fp="12,263,13.353.0,16.350.0,20.265.0,30.156.0,34.190.0,30.197.0,54.178.0,21.180.0,47.152.0"}
